-- ============================================================
-- Article archive — the 71 articles the website shipped as
-- data/articles.json, imported into the CMS.
--
-- Run AFTER article_content.sql.
--
-- Idempotent: matched on slug, so re-running refreshes the archive without
-- creating duplicates. It only ever touches these slugs — anything written
-- in the admin is left alone.
--
-- `blocks` holds the original typed array and is what the API serves.
-- `content` is an HTML rendering of the same thing so the article can be
-- opened in the editor; saving there clears blocks and takes ownership.
-- ============================================================

insert into articles (slug, title, excerpt, content, cover_image_url, category, tags, status, published_at, blocks) values
  ('cambridge-university-arrive-in-ghana-for-landmark-rugby-league-tour', 'Cambridge University arrive in Ghana for landmark rugby league tour', 'The Cambridge University Rugby League team has arrived in Ghana ahead of a landmark week-long tour aimed at strengthening international sporting links and supporting the continued growth of rugby league in West Africa.', '<p>The touring squad landed in Accra on Monday evening to begin a seven-day programme of competitive fixtures, coaching, school visits and community engagement.</p>
<p>Organised by the Rugby League Federation Ghana (RLFG), the tour reflects the growing relationship between Ghanaian rugby league and one of England&#x27;s oldest and most prestigious university sporting institutions.</p>
<img src="/news/cb2.jpeg" alt="">
<p>The visit follows the successful tour of the Oxford University Rugby League Club in 2022, further highlighting Ghana&#x27;s emergence as an international destination for university rugby league and reinforcing the Rugby League Federation Ghana&#x27;s commitment to building long-term partnerships through sport.</p>
<p>Cambridge will play three matches during the tour, beginning with a 9-a-side fixture against the University of Ghana on Tuesday, before facing the President&#x27;s XIII on Thursday. The visitors will conclude their stay with an international fixture against the Ghana Leopards national team on Sunday. All three matches will be played at the University of Ghana Rugby Stadium in Accra.</p>
<p>Away from the pitch, the Cambridge delegation will visit schools, participate in rugby development sessions and engage with community organisations as part of a programme designed to promote cultural exchange alongside sporting competition.</p>
<p>The Rugby League Federation Ghana says the visit represents another milestone in its efforts to expand the sport through international partnerships and provide Ghanaian players with opportunities to compete against high-quality opposition.</p>
<p>RLFG General Manager Jafaru Mustapha said the tour demonstrates how rugby league can create lasting relationships beyond competition. “This is a proud moment for rugby league in Ghana. Welcoming Cambridge University is a reflection of how far the sport has developed in recent years. We believe this tour will inspire young players, strengthen international friendships and leave a lasting legacy for rugby league in Ghana.”</p>
<p>With three matches, school visits, coaching clinics and community engagement activities scheduled throughout the week, the tour is expected to leave a lasting legacy for players, coaches and young people, while further enhancing Ghana&#x27;s reputation as an emerging nation in international rugby league.</p>', '/news/cb1.jpeg', 'News', '{}'::text[], 'published', '2026-07-07'::timestamptz, '[{"type": "paragraph", "content": "The touring squad landed in Accra on Monday evening to begin a seven-day programme of competitive fixtures, coaching, school visits and community engagement."}, {"type": "paragraph", "content": "Organised by the Rugby League Federation Ghana (RLFG), the tour reflects the growing relationship between Ghanaian rugby league and one of England''s oldest and most prestigious university sporting institutions."}, {"type": "image", "src": "/news/cb2.jpeg", "size": "contain"}, {"type": "paragraph", "content": "The visit follows the successful tour of the Oxford University Rugby League Club in 2022, further highlighting Ghana''s emergence as an international destination for university rugby league and reinforcing the Rugby League Federation Ghana''s commitment to building long-term partnerships through sport."}, {"type": "paragraph", "content": "Cambridge will play three matches during the tour, beginning with a 9-a-side fixture against the University of Ghana on Tuesday, before facing the President''s XIII on Thursday. The visitors will conclude their stay with an international fixture against the Ghana Leopards national team on Sunday. All three matches will be played at the University of Ghana Rugby Stadium in Accra."}, {"type": "paragraph", "content": "Away from the pitch, the Cambridge delegation will visit schools, participate in rugby development sessions and engage with community organisations as part of a programme designed to promote cultural exchange alongside sporting competition."}, {"type": "paragraph", "content": "The Rugby League Federation Ghana says the visit represents another milestone in its efforts to expand the sport through international partnerships and provide Ghanaian players with opportunities to compete against high-quality opposition."}, {"type": "paragraph", "content": "RLFG General Manager Jafaru Mustapha said the tour demonstrates how rugby league can create lasting relationships beyond competition. “This is a proud moment for rugby league in Ghana. Welcoming Cambridge University is a reflection of how far the sport has developed in recent years. We believe this tour will inspire young players, strengthen international friendships and leave a lasting legacy for rugby league in Ghana.”"}, {"type": "paragraph", "content": "With three matches, school visits, coaching clinics and community engagement activities scheduled throughout the week, the tour is expected to leave a lasting legacy for players, coaches and young people, while further enhancing Ghana''s reputation as an emerging nation in international rugby league."}]'::jsonb),
  ('rangers-rugby-league-schhol-queenslan-crowned-championsp-at-rising-starts-tournament', 'Rangers Rugby League School and Queensland International School Crowned Champions at Rising Stars Rugby League Tournament – Accra Edition 2.0', 'Accra, Ghana – June 12, 2026 – The Rugby League Federation Ghana (RLFG) successfully hosted the second edition of the Rising Stars Rugby League Tournament – Accra Edition at the University of Ghana Rugby Stadium, further strengthening its commitment to grassroots rugby league development in the country.', '<p>The competition brought together five boy teams—Queensland Team A &amp; B, Rangers Team A &amp; B, and Futurestars Charity—as well as three girl teams—Queensland Team A &amp; B and Futurestars Charity. All teams competed in an all-play-all format, ensuring each team faced every other team in their respective divisions.</p>
<p>The competition showcased exciting displays of teamwork, speed and determination from some of Ghana&#x27;s emerging rugby league talents.</p>
<img src="/news/rlfg_int_boys.jpeg" alt="">
<p>In the boys&#x27; division, defending champions Queensland International School were unable to retain the title they won in the maiden edition of the Rising Stars Tournament. Tournament debutants Rangers Team A of Rangers Rugby League School rose to the occasion, delivering a series of outstanding performances to emerge as champions in their first-ever appearance at the competition.</p>
<p>Rangers Team A began their campaign in impressive fashion, securing an 8–2 victory over Queensland Team B before defeating Future Leaders Boys 8–0 and Rangers Team B 3–1. They then capped off an unbeaten run with a 5–3 win over Queensland Team A to claim the tournament title. Queensland Team A finished as runners-up, followed by Rangers Team B in third place, Queensland Team B in fourth, and Future Leaders Boys in fifth.</p>
<img src="/news/rlfg_int_girls.jpeg" alt="">
<p>In the girls&#x27; division, however, it was a case of familiar celebrations as Queensland Team A of Queensland International School successfully defended their title to become back-to-back Rising Stars Tournament champions, reaffirming their dominance in the competition.</p>
<p>Queensland Team A opened their campaign with a hard-fought 5–4 victory over Queensland Team B before securing the championship with a 3–1 win against Future Leaders. Their two victories ensured they finished top of the standings and retained their crown. Future Leaders claimed second place after a strong showing throughout the tournament, while Queensland Team B finished in third place</p>
<p>Speaking on the significance of the tournament, Greater Accra Rugby League Vice President, Mrs Paulina Buabeng, reiterated the region&#x27;s commitment to creating opportunities for children and young people to engage with rugby league in a structured, safe, and supportive environment.</p>
<p>“The Rising Stars Tournament continues to provide an important platform for young people to participate in rugby league, develop their skills, build confidence, and enjoy the benefits of sport. We remain committed to creating more opportunities for children and young people across the Greater Accra Region to engage with the game,” she said.</p>
<p>RLFG Technical Director Marshall Nortey highlighted the tournament&#x27;s growing impact on player development and talent identification.</p>
<p>“With two successful editions now completed, the Rising Stars Rugby League Tournament continues to establish itself as a key platform for identifying and nurturing the next generation of rugby league talent in Ghana. The quality of competition and enthusiasm displayed by the participants demonstrate the bright future of the sport in the country,” he said.</p>
<p>As the tournament continues to grow, the Rising Stars Rugby League Tournament remains true to its purpose: providing young people with opportunities to compete, learn valuable life skills, and dream bigger through rugby league.</p>', '/news/rlfg_int.jpeg', 'News', '{}'::text[], 'published', '2025-12-18'::timestamptz, '[{"type": "paragraph", "content": "The competition brought together five boy teams—Queensland Team A & B, Rangers Team A & B, and Futurestars Charity—as well as three girl teams—Queensland Team A & B and Futurestars Charity. All teams competed in an all-play-all format, ensuring each team faced every other team in their respective divisions."}, {"type": "paragraph", "content": "The competition showcased exciting displays of teamwork, speed and determination from some of Ghana''s emerging rugby league talents."}, {"type": "image", "src": "/news/rlfg_int_boys.jpeg", "size": "contain"}, {"type": "paragraph", "content": "In the boys'' division, defending champions Queensland International School were unable to retain the title they won in the maiden edition of the Rising Stars Tournament. Tournament debutants Rangers Team A of Rangers Rugby League School rose to the occasion, delivering a series of outstanding performances to emerge as champions in their first-ever appearance at the competition."}, {"type": "paragraph", "content": "Rangers Team A began their campaign in impressive fashion, securing an 8–2 victory over Queensland Team B before defeating Future Leaders Boys 8–0 and Rangers Team B 3–1. They then capped off an unbeaten run with a 5–3 win over Queensland Team A to claim the tournament title. Queensland Team A finished as runners-up, followed by Rangers Team B in third place, Queensland Team B in fourth, and Future Leaders Boys in fifth."}, {"type": "image", "src": "/news/rlfg_int_girls.jpeg", "size": "contain"}, {"type": "paragraph", "content": "In the girls'' division, however, it was a case of familiar celebrations as Queensland Team A of Queensland International School successfully defended their title to become back-to-back Rising Stars Tournament champions, reaffirming their dominance in the competition."}, {"type": "paragraph", "content": "Queensland Team A opened their campaign with a hard-fought 5–4 victory over Queensland Team B before securing the championship with a 3–1 win against Future Leaders. Their two victories ensured they finished top of the standings and retained their crown. Future Leaders claimed second place after a strong showing throughout the tournament, while Queensland Team B finished in third place"}, {"type": "paragraph", "content": "Speaking on the significance of the tournament, Greater Accra Rugby League Vice President, Mrs Paulina Buabeng, reiterated the region''s commitment to creating opportunities for children and young people to engage with rugby league in a structured, safe, and supportive environment."}, {"type": "paragraph", "content": "“The Rising Stars Tournament continues to provide an important platform for young people to participate in rugby league, develop their skills, build confidence, and enjoy the benefits of sport. We remain committed to creating more opportunities for children and young people across the Greater Accra Region to engage with the game,” she said."}, {"type": "paragraph", "content": "RLFG Technical Director Marshall Nortey highlighted the tournament''s growing impact on player development and talent identification."}, {"type": "paragraph", "content": "“With two successful editions now completed, the Rising Stars Rugby League Tournament continues to establish itself as a key platform for identifying and nurturing the next generation of rugby league talent in Ghana. The quality of competition and enthusiasm displayed by the participants demonstrate the bright future of the sport in the country,” he said."}, {"type": "paragraph", "content": "As the tournament continues to grow, the Rising Stars Rugby League Tournament remains true to its purpose: providing young people with opportunities to compete, learn valuable life skills, and dream bigger through rugby league."}]'::jsonb),
  ('rlfg-achieves-full-membership-of-the-international-rugby-league', 'Ghana Rugby League Achieves Full Membership of the International Rugby League', 'Rugby League Federation Ghana (RLFG) has been officially approved as the 15th Full Member of the International Rugby League (IRL) following the IRL Annual General Meeting held on 18 December 2025.', '<p>The historic achievement crowns a 13-year journey that began in 2012 through a collaboration between sponsors Hector and Sara Giwa-McNeil, the British Government, and European Rugby League, which introduced rugby league into leadership development initiatives and led to the establishment of RLFG in 2014. Ghana attained affiliate membership within six years and has now become the first national federation to achieve Full Membership under the IRL policy introduced in 2019, a framework designed to promote strong governance, financial prudence, operational proficiency, and sustainable growth.</p>
<p>IRL Chair Troy Grant said: “On behalf of the IRL Board, I would like to congratulate RLFG for this fantastic achievement. Since the project began in 2012, the Ghanaian rugby league community has gone from strength to strength and is a true testament to what can be achieved with good governance. From schools to national teams, domestic pathways exist and a genuine rugby league community has been created and nurtured.”</p>
<img src="/news/irl_1.jpeg" alt="">
<p>Between July 2024 and June 2025, RLFG’s volunteers and trained school educators delivered rugby league to approximately 2,000 participants through over 400 training sessions across 30 schools, six clubs, and four regions (Greater Accra, Volta, Ashanti, and Northern Region). Community programmes include partnerships with the Nineka Youth Foundation Youth Empowerment Camp, beach rugby league and beach clean-up initiatives, and breast and prostate cancer screening campaigns.</p>
<p>Ghana is also a leader in technical education, becoming the first Middle East–Africa nation to achieve full compliance with the IRL Technical Education Framework. RLFG has two IRL Level 1 Coach Educators, three IRL Level 1 Match Official Educators (including one woman), seven accredited IRL Level 1 Coaches, and 11 IRL Level 1 Match Officials.</p>
<p>At representative level, Ghana has fielded national teams since 2019, hosted the MEA Championship in 2022, introduced a women’s national team in 2023, and continues to develop talent through domestic representative competitions such as the Origins Cup and President’s Cup.</p>
<p>RLFG President Juliana Storey said: “This is a moment of immense joy and pride for Ghana. This achievement reflects the dedication, resilience, and belief of our players, clubs, officials, volunteers, partners, and stakeholders. We are committed to upholding the highest standards of the IRL and to continuing the sustainable development of rugby league in Ghana and across Africa.”</p>
<p>Ghana becomes the second Full Member from the Middle East–Africa region, alongside South Africa, and the first new IRL Full Member since Italy in 2017.</p>', '/news/irl_cover.jpeg', 'News', '{}'::text[], 'published', '2025-12-18'::timestamptz, '[{"type": "paragraph", "content": "The historic achievement crowns a 13-year journey that began in 2012 through a collaboration between sponsors Hector and Sara Giwa-McNeil, the British Government, and European Rugby League, which introduced rugby league into leadership development initiatives and led to the establishment of RLFG in 2014. Ghana attained affiliate membership within six years and has now become the first national federation to achieve Full Membership under the IRL policy introduced in 2019, a framework designed to promote strong governance, financial prudence, operational proficiency, and sustainable growth."}, {"type": "paragraph", "content": "IRL Chair Troy Grant said: “On behalf of the IRL Board, I would like to congratulate RLFG for this fantastic achievement. Since the project began in 2012, the Ghanaian rugby league community has gone from strength to strength and is a true testament to what can be achieved with good governance. From schools to national teams, domestic pathways exist and a genuine rugby league community has been created and nurtured.”"}, {"type": "image", "src": "/news/irl_1.jpeg", "size": "contain"}, {"type": "paragraph", "content": "Between July 2024 and June 2025, RLFG’s volunteers and trained school educators delivered rugby league to approximately 2,000 participants through over 400 training sessions across 30 schools, six clubs, and four regions (Greater Accra, Volta, Ashanti, and Northern Region). Community programmes include partnerships with the Nineka Youth Foundation Youth Empowerment Camp, beach rugby league and beach clean-up initiatives, and breast and prostate cancer screening campaigns."}, {"type": "paragraph", "content": "Ghana is also a leader in technical education, becoming the first Middle East–Africa nation to achieve full compliance with the IRL Technical Education Framework. RLFG has two IRL Level 1 Coach Educators, three IRL Level 1 Match Official Educators (including one woman), seven accredited IRL Level 1 Coaches, and 11 IRL Level 1 Match Officials."}, {"type": "paragraph", "content": "At representative level, Ghana has fielded national teams since 2019, hosted the MEA Championship in 2022, introduced a women’s national team in 2023, and continues to develop talent through domestic representative competitions such as the Origins Cup and President’s Cup."}, {"type": "paragraph", "content": "RLFG President Juliana Storey said: “This is a moment of immense joy and pride for Ghana. This achievement reflects the dedication, resilience, and belief of our players, clubs, officials, volunteers, partners, and stakeholders. We are committed to upholding the highest standards of the IRL and to continuing the sustainable development of rugby league in Ghana and across Africa.”"}, {"type": "paragraph", "content": "Ghana becomes the second Full Member from the Middle East–Africa region, alongside South Africa, and the first new IRL Full Member since Italy in 2017."}]'::jsonb),
  ('tri-nation-rugby-league-festival-a-powerful-finish-to-three-days-of-pure-rugby-league-action', 'THE TRI-NATION RUGBY LEAGUE FESTIVAL — A POWERFUL FINISH TO THREE DAYS OF PURE RUGBY LEAGUE ACTION', 'The final day of the 2025 Tri-Nation Rugby League Festival wrapped up in style at the University of Ghana Rugby Stadium — the perfect finish to three action-packed match days (Nov 23, 26 & 30).', '<p>We opened the day with two exciting youth exhibition games between Greater Accra and the Ashanti Region. The girls kicked things off, with Ashanti Region defeating Greater Accra 34–0. In the boys’ match, Greater Accra edged Ashanti Region 10–6 in a tight contest.</p>
<p>Then came the main fixtures — Ghana’s national teams meeting Roots Rugby (USA) for the second time.</p>
<p>In the women’s game, Roots came out strong once again, beating the Ghana National Women’s Team 38–0. But the men closed the entire festival with a huge moment — the Ghana Men’s National Team earned their first-ever win over Roots, taking the final match 28–16.</p>
<p>[{&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/men_tri.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/women_tri.jpeg&#x27;}]</p>
<p>Beyond the field action, this year’s festival also marked a major step forward in Ghana’s technical development. IRL Referee Educator James Jones delivered an intensive officiating program, working with Ghanaian match officials throughout the week to raise standards and support Ghana’s journey toward full IRL membership. His presence, insights, and training were a significant highlight of the festival.</p>
<p><strong>MEN RESULTS</strong></p>
<ul><li>Ghana 36–24 Nigeria</li><li>Presidents Team 28–38 Roots</li><li>Ghana 28–16 Roots</li></ul>
<p><strong>WOMEN RESULTS</strong></p>
<ul><li>Ghana 8–42 Nigeria</li><li>Ghana 8–30 Roots</li><li>Ghana 0–38 Roots</li></ul>
<p><strong>YOUTH RESULTS</strong></p>
<ul><li>Greater Accra Boys 10–6 Ashanti</li><li>Greater Accra Girls 0–34 Ashanti</li></ul>
<p>Every match added its own story, energy, and contribution to the growth of rugby league in Ghana.</p>
<p>From national pride and youth development to international experience and world-class officiating training, the Tri-Nation Festival showcased how far rugby league has come — and how boldly Ghana is stepping into the future.</p>', '/news/tri_cover.jpeg', 'News', '{}'::text[], 'published', '2025-12-01'::timestamptz, '[{"type": "paragraph", "content": "We opened the day with two exciting youth exhibition games between Greater Accra and the Ashanti Region. The girls kicked things off, with Ashanti Region defeating Greater Accra 34–0. In the boys’ match, Greater Accra edged Ashanti Region 10–6 in a tight contest."}, {"type": "paragraph", "content": "Then came the main fixtures — Ghana’s national teams meeting Roots Rugby (USA) for the second time."}, {"type": "paragraph", "content": "In the women’s game, Roots came out strong once again, beating the Ghana National Women’s Team 38–0. But the men closed the entire festival with a huge moment — the Ghana Men’s National Team earned their first-ever win over Roots, taking the final match 28–16."}, {"type": "gallery", "content": [{"type": "image", "src": "/news/men_tri.jpeg"}, {"type": "image", "src": "/news/women_tri.jpeg"}]}, {"type": "paragraph", "content": "Beyond the field action, this year’s festival also marked a major step forward in Ghana’s technical development. IRL Referee Educator James Jones delivered an intensive officiating program, working with Ghanaian match officials throughout the week to raise standards and support Ghana’s journey toward full IRL membership. His presence, insights, and training were a significant highlight of the festival."}, {"type": "list", "name": "MEN RESULTS", "content": ["Ghana 36–24 Nigeria", "Presidents Team 28–38 Roots", "Ghana 28–16 Roots"], "attrs": {"bullets": true}}, {"type": "list", "name": "WOMEN RESULTS", "content": ["Ghana 8–42 Nigeria", "Ghana 8–30 Roots", "Ghana 0–38 Roots"], "attrs": {"bullets": true}}, {"type": "list", "name": "YOUTH RESULTS", "content": ["Greater Accra Boys 10–6 Ashanti", "Greater Accra Girls 0–34 Ashanti"], "attrs": {"bullets": true}}, {"type": "paragraph", "content": "Every match added its own story, energy, and contribution to the growth of rugby league in Ghana."}, {"type": "paragraph", "content": "From national pride and youth development to international experience and world-class officiating training, the Tri-Nation Festival showcased how far rugby league has come — and how boldly Ghana is stepping into the future."}]'::jsonb),
  ('nsa-director-general-motivates-ghana-womens-rugby-league-team-ahead-of-nigeria-test-series', 'NSA Director General Motivates Ghana Women’s Rugby League Team Ahead of Nigeria Test Series', 'The Director General of the National Sports Authority (NSA), Yaw Ampofo Ankrah, paid a surprise visit on Sunday, September 28th, to the Ghana Women’s National Rugby League Team, the Leopardess, as they wrapped up their final training session at the University of Ghana Rugby Stadium.', '<p>The Leopardess are set to travel to Lagos for a highly anticipated three-game international rugby league test series against Nigeria, scheduled for October 4th, 7th, and 11th, 2025.</p>
<p>During his visit, the Director General spent quality time with the players, offering words of encouragement and personally engaging with the squad. He urged the team to remain focused, disciplined, and united as they prepare to represent Ghana on foreign soil.</p>
<p>“I believe in your talent and determination. I can see this is a very young team, and that really reflects the future plans of the federation. Representing the country at this stage is a big responsibility, but it is also a step towards growth. Go out there, play with pride, and make Ghana proud. You carry the hopes of a nation with you.” – Yaw Ampofo Ankrah, Director General, NSA</p>
<p>[{&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/nsa2.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/nsa3.jpeg&#x27;}]</p>
<p>His presence provided an extra boost of motivation for the players, who expressed their appreciation for his support. The NSA Director also reaffirmed the Authority’s commitment to backing the growth of women’s sports in Ghana and emphasized the Leopardess’ role as pioneers in flying the country’s flag high on the international rugby league stage.</p>
<p>Currently ranked 24th in the world, the Leopardess will be represented by: Accra Ladies – Elizabeth Adongo (Captain), Millicent Njomaba, Jacqueline Ansah, Hilaria Wuaku (Assistant Captain), Princess Avorkah, Gracelove Hammond, Fati Bhom, Ivy Benyah, Gifty Sowah, Eunice Lawoe</p>
<p>Awutu Ladies – Celestine Kumah, Mariama Musah, Minawara Alhassan, Henrietta Arhin</p>
<p>Schools – Grace Nketiah (Pentecost SHS), Maria Tii Pegyine (St. Michaels SHS), Kesse Mary (Afigya Secondary Technical), Christiana Ndewine (Aduman Secondary)</p>
<p>Coaches – Riddick Alibah, Julius Fiakpornu</p>
<p>With the Director General’s encouragement fresh in their minds, the Leopardess now turn their attention to Nigeria with renewed confidence, determined to bring glory to Ghana.</p>', '/news/nsa.jpeg', 'News', '{}'::text[], 'published', '2025-09-29'::timestamptz, '[{"type": "paragraph", "content": "The Leopardess are set to travel to Lagos for a highly anticipated three-game international rugby league test series against Nigeria, scheduled for October 4th, 7th, and 11th, 2025."}, {"type": "paragraph", "content": "During his visit, the Director General spent quality time with the players, offering words of encouragement and personally engaging with the squad. He urged the team to remain focused, disciplined, and united as they prepare to represent Ghana on foreign soil."}, {"type": "paragraph", "content": "“I believe in your talent and determination. I can see this is a very young team, and that really reflects the future plans of the federation. Representing the country at this stage is a big responsibility, but it is also a step towards growth. Go out there, play with pride, and make Ghana proud. You carry the hopes of a nation with you.” – Yaw Ampofo Ankrah, Director General, NSA"}, {"type": "gallery", "content": [{"type": "image", "src": "/news/nsa2.jpeg"}, {"type": "image", "src": "/news/nsa3.jpeg"}]}, {"type": "paragraph", "content": "His presence provided an extra boost of motivation for the players, who expressed their appreciation for his support. The NSA Director also reaffirmed the Authority’s commitment to backing the growth of women’s sports in Ghana and emphasized the Leopardess’ role as pioneers in flying the country’s flag high on the international rugby league stage."}, {"type": "paragraph", "content": "Currently ranked 24th in the world, the Leopardess will be represented by: Accra Ladies – Elizabeth Adongo (Captain), Millicent Njomaba, Jacqueline Ansah, Hilaria Wuaku (Assistant Captain), Princess Avorkah, Gracelove Hammond, Fati Bhom, Ivy Benyah, Gifty Sowah, Eunice Lawoe"}, {"type": "paragraph", "content": "Awutu Ladies – Celestine Kumah, Mariama Musah, Minawara Alhassan, Henrietta Arhin"}, {"type": "paragraph", "content": "Schools – Grace Nketiah (Pentecost SHS), Maria Tii Pegyine (St. Michaels SHS), Kesse Mary (Afigya Secondary Technical), Christiana Ndewine (Aduman Secondary)"}, {"type": "paragraph", "content": "Coaches – Riddick Alibah, Julius Fiakpornu"}, {"type": "paragraph", "content": "With the Director General’s encouragement fresh in their minds, the Leopardess now turn their attention to Nigeria with renewed confidence, determined to bring glory to Ghana."}]'::jsonb),
  ('ashanti-youth-rugby-league-13s-officially-launched', '2025 Ashanti Youth Rugby League 13s Championship Officially Launched', 'The Rugby League Federation Ghana (RLFG) has officially launched the 2025 Ashanti Youth Rugby League 13s Championship, marking a significant step in the promotion and development of the sport in the region.', '<p>The championship would feature four pioneering schools: Aduman Senior High School, Pentecost Senior High School, Afigya Secondary &amp; Technical School and St. Michael Senior High School. Each school will field both boys’ and girls’ teams, demonstrating Ashanti Regional Rugby League Association’s commitment to inclusivity and youth engagement.</p>
<p>[{&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/ash_1.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/ash_4.jpg&#x27;}]</p>
<p>The launch, held on September 3, 2025, was attended by physical education teachers and the captains of the boys’ and girls’ teams from the participating schools. Their presence emphasized the direct involvement of young athletes and educators in shaping the future of Rugby League in Ashanti.</p>
<p>Speaking at the event, Nana Adu Gyamfi Kumanin Barima Kese I, Chairman and Life Patron of the Ashanti Rugby League Association, underscored the importance of the initiative. “This championship is not just about competition. It is about giving young people the opportunity to learn teamwork, discipline, and leadership while showcasing their talent on a bigger stage,” he said.</p>
<p>Speaking at the event, Nana Adu Gyamfi Kumanin Barima Kese I, Chairman and Life Patron of the Ashanti Rugby League Association, underscored the importance of the initiative. “This championship is not just about competition. It is about giving young people the opportunity to learn teamwork, discipline, and leadership while showcasing their talent on a bigger stage,” he said.</p>
<p>The championship will run alongside an eight-week youth league from September 5 to October 24, providing consistent competitive opportunities for the participating schools. The competition will also serve as the basis for selecting a regional team to represent the Ashanti Region, while the girls’ division will provide a pathway for players to join the female national team ahead of upcoming tournaments in Nigeria in October and Ghana in November.</p>
<p>The launch of the 2025 Ashanti Youth Rugby League 13s Championship has been welcomed with enthusiasm by students, teachers, and the wider sporting community, who view it as a turning point for Rugby League development in the Ashanti Region.</p>', '/news/ash_1.jpeg', 'News', '{}'::text[], 'published', '2025-08-05'::timestamptz, '[{"type": "paragraph", "content": "The championship would feature four pioneering schools: Aduman Senior High School, Pentecost Senior High School, Afigya Secondary & Technical School and St. Michael Senior High School. Each school will field both boys’ and girls’ teams, demonstrating Ashanti Regional Rugby League Association’s commitment to inclusivity and youth engagement."}, {"type": "gallery", "content": [{"type": "image", "src": "/news/ash_1.jpeg"}, {"type": "image", "src": "/news/ash_4.jpg"}]}, {"type": "paragraph", "content": "The launch, held on September 3, 2025, was attended by physical education teachers and the captains of the boys’ and girls’ teams from the participating schools. Their presence emphasized the direct involvement of young athletes and educators in shaping the future of Rugby League in Ashanti."}, {"type": "paragraph", "content": "Speaking at the event, Nana Adu Gyamfi Kumanin Barima Kese I, Chairman and Life Patron of the Ashanti Rugby League Association, underscored the importance of the initiative. “This championship is not just about competition. It is about giving young people the opportunity to learn teamwork, discipline, and leadership while showcasing their talent on a bigger stage,” he said."}, {"type": "paragraph", "content": "Speaking at the event, Nana Adu Gyamfi Kumanin Barima Kese I, Chairman and Life Patron of the Ashanti Rugby League Association, underscored the importance of the initiative. “This championship is not just about competition. It is about giving young people the opportunity to learn teamwork, discipline, and leadership while showcasing their talent on a bigger stage,” he said."}, {"type": "paragraph", "content": "The championship will run alongside an eight-week youth league from September 5 to October 24, providing consistent competitive opportunities for the participating schools. The competition will also serve as the basis for selecting a regional team to represent the Ashanti Region, while the girls’ division will provide a pathway for players to join the female national team ahead of upcoming tournaments in Nigeria in October and Ghana in November."}, {"type": "paragraph", "content": "The launch of the 2025 Ashanti Youth Rugby League 13s Championship has been welcomed with enthusiasm by students, teachers, and the wider sporting community, who view it as a turning point for Rugby League development in the Ashanti Region."}]'::jsonb),
  ('nana-adu-gyamfi-leads-new-ashanti-rugby-league-leadership', 'Nana Adu Gyamfi Kumanin Barima Kese Leads New Ashanti Rugby League Leadership', 'The Rugby League Federation Ghana (RLFG) has constituted a new leadership team for the Ashanti Region as part of efforts to strengthen the sport’s structures and promote its growth nationwide.', '<p>The newly appointed executives, who will serve a two-year mandate, are expected to lead the regional association in promoting Rugby League, nurturing young talent, and expanding participation across schools, communities, and workplaces. Their tenure will culminate in an elective congress at the end of the mandate.</p>
<p>[{&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/ash.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/ash_2.jpg&#x27;}]</p>
<p>At the helm of the new leadership is Nana Adu Gyamfi Kumanin Barima Kese I, Nyankyerenease Nkosuohene, who also serves on the RLFG Board. A respected entrepreneur and Chief Executive Officer of Shamore Herbal, Nana Adu Gyamfi assumes the role of chairman and life patron. He brings to the position a wealth of experience in business development, community leadership, and strategic partnerships. His long-standing commitment to youth empowerment, education, and public health aligns closely with the RLFG’s vision of using Rugby League as a tool for transformation and national development.</p>
<p>The new leadership team includes Vice Chairperson, David Akomeah Asokwah, Regional Manager (Technical) Julius Amevor, Regional Manager (Organising) George Asamoah, Secretary Gloria Agbenyikey, Treasurer Mr. Ebenezer Boakye, Marketing and Sponsorship Officer Kingsford Osei Boateng, Branding and Communication Officer Kwabena Obeng Frimpong, NSA Liaison, Andrew Kobina Nyamoah, Deaf Rugby League, Mr. Benjamin Annor and GES Liaison Philip Asibey.</p>
<p>The executives were formally sworn in on Wednesday September 3, 2025 at Baba Yara Stadium, by the Ashanti Regional Regional Director Nana Gyaama Darkwa, Technical Director of the National Sports Authority (NSA), Mr. Simon Koku Gluikpor and Joshua Sekyere Korankye, the Regional Administrator of the National Sports Authority (NSA) and Mr. Jafaru Awudu Mustapha, General Manager Rugby League Federation Ghana.</p>
<p>RLFG General Manager, Mr. Jafaru Awudu Mustapha, commended the new executives for accepting the call to serve and urged them to remain committed to the Federation’s broader vision: “This inauguration marks another important step in our mission to spread rugby league across Ghana. The Ashanti Region holds great potential, and with this new leadership in place, we are confident the game will reach more schools, communities, and workplaces. I urge the executives to lead with integrity, passion, and innovation as we continue to build structures that will prepare Ghana for future international success.”</p>
<p>Their collective mandate is to promote and develop Rugby League in the Ashanti Region, identify and nurture young athletes, organize regional competitions and events, collaborate with national and international Rugby League bodies to create opportunities for players, increase participation in schools, communities, and workplaces, and provide training and capacity building for coaches, officials, and athletes. They are also expected to support the formation of Rugby League clubs to boost grassroots development.</p>
<p>Already, plans are underway for the organization of an officiating course and an eight-week youth league for boys and girls, scheduled to take place from September 5 to October 24.</p>
<p>Ashanti Regional Director of Sports, Nana Gyaama Darkwa, praised RLFG’s sustained efforts: “I am truly excited and overwhelmed by the tremendous work Rugby League has done in the regions over the years. This new leadership gives me confidence that the Ashanti Region will become a strong pillar in the sport’s national growth.</p>
<p>In his remarks after the appointment, Nana Adu Gyamfi Kumanin Barima Kese I expressed optimism about the future of Rugby League in the Ashanti Region. “We are excited to take on this challenge and contribute to the growth and development of Rugby League in the Ashanti Region,” he said.</p>
<p>Vice Chairperson David Akomeah Asokwah also called on stakeholders and the wider public to support the initiative. “We look forward to working with all partners to achieve our goals and make Rugby League a force to be reckoned with in the region,” he noted.</p>
<p>The appointment of the new executives has been welcomed with enthusiasm by members of the Rugby League community, who remain optimistic about the positive impact the leadership will bring. With their combined expertise and passion, the future of Rugby League in the Ashanti Region appears promising.</p>', '/news/ash.jpeg', 'News', '{}'::text[], 'published', '2025-08-05'::timestamptz, '[{"type": "paragraph", "content": "The newly appointed executives, who will serve a two-year mandate, are expected to lead the regional association in promoting Rugby League, nurturing young talent, and expanding participation across schools, communities, and workplaces. Their tenure will culminate in an elective congress at the end of the mandate."}, {"type": "gallery", "content": [{"type": "image", "src": "/news/ash.jpeg"}, {"type": "image", "src": "/news/ash_2.jpg"}]}, {"type": "paragraph", "content": "At the helm of the new leadership is Nana Adu Gyamfi Kumanin Barima Kese I, Nyankyerenease Nkosuohene, who also serves on the RLFG Board. A respected entrepreneur and Chief Executive Officer of Shamore Herbal, Nana Adu Gyamfi assumes the role of chairman and life patron. He brings to the position a wealth of experience in business development, community leadership, and strategic partnerships. His long-standing commitment to youth empowerment, education, and public health aligns closely with the RLFG’s vision of using Rugby League as a tool for transformation and national development."}, {"type": "paragraph", "content": "The new leadership team includes Vice Chairperson, David Akomeah Asokwah, Regional Manager (Technical) Julius Amevor, Regional Manager (Organising) George Asamoah, Secretary Gloria Agbenyikey, Treasurer Mr. Ebenezer Boakye, Marketing and Sponsorship Officer Kingsford Osei Boateng, Branding and Communication Officer Kwabena Obeng Frimpong, NSA Liaison, Andrew Kobina Nyamoah, Deaf Rugby League, Mr. Benjamin Annor and GES Liaison Philip Asibey."}, {"type": "paragraph", "content": "The executives were formally sworn in on Wednesday September 3, 2025 at Baba Yara Stadium, by the Ashanti Regional Regional Director Nana Gyaama Darkwa, Technical Director of the National Sports Authority (NSA), Mr. Simon Koku Gluikpor and Joshua Sekyere Korankye, the Regional Administrator of the National Sports Authority (NSA) and Mr. Jafaru Awudu Mustapha, General Manager Rugby League Federation Ghana."}, {"type": "paragraph", "content": "RLFG General Manager, Mr. Jafaru Awudu Mustapha, commended the new executives for accepting the call to serve and urged them to remain committed to the Federation’s broader vision: “This inauguration marks another important step in our mission to spread rugby league across Ghana. The Ashanti Region holds great potential, and with this new leadership in place, we are confident the game will reach more schools, communities, and workplaces. I urge the executives to lead with integrity, passion, and innovation as we continue to build structures that will prepare Ghana for future international success.”"}, {"type": "paragraph", "content": "Their collective mandate is to promote and develop Rugby League in the Ashanti Region, identify and nurture young athletes, organize regional competitions and events, collaborate with national and international Rugby League bodies to create opportunities for players, increase participation in schools, communities, and workplaces, and provide training and capacity building for coaches, officials, and athletes. They are also expected to support the formation of Rugby League clubs to boost grassroots development."}, {"type": "paragraph", "content": "Already, plans are underway for the organization of an officiating course and an eight-week youth league for boys and girls, scheduled to take place from September 5 to October 24."}, {"type": "paragraph", "content": "Ashanti Regional Director of Sports, Nana Gyaama Darkwa, praised RLFG’s sustained efforts: “I am truly excited and overwhelmed by the tremendous work Rugby League has done in the regions over the years. This new leadership gives me confidence that the Ashanti Region will become a strong pillar in the sport’s national growth."}, {"type": "paragraph", "content": "In his remarks after the appointment, Nana Adu Gyamfi Kumanin Barima Kese I expressed optimism about the future of Rugby League in the Ashanti Region. “We are excited to take on this challenge and contribute to the growth and development of Rugby League in the Ashanti Region,” he said."}, {"type": "paragraph", "content": "Vice Chairperson David Akomeah Asokwah also called on stakeholders and the wider public to support the initiative. “We look forward to working with all partners to achieve our goals and make Rugby League a force to be reckoned with in the region,” he noted."}, {"type": "paragraph", "content": "The appointment of the new executives has been welcomed with enthusiasm by members of the Rugby League community, who remain optimistic about the positive impact the leadership will bring. With their combined expertise and passion, the future of Rugby League in the Ashanti Region appears promising."}]'::jsonb),
  ('kofi-montchon-crowned-rlfg-player-of-the-month-for-july', 'Kofi Montchon Crowned RLFG Player of the Month for July', 'The Rugby League Federation Ghana (RLFG) has named Kofi Montchon of Nungua Tigers as the Player of the Month for July in the ongoing 2025 RLFG Men’s 13s Championship', '<p>Montchon, who plays at standoff, has been a driving force in the Tigers’ campaign, combining vision, game control, and accurate kicking to steer his team through key fixtures. His consistency and leadership earned him overwhelming support in the fan vote, making him the clear choice for the award.</p>
<img src="/news/montchon.jpeg" alt="">
<p>In July, Montchon produced standout performances, including scoring two tries and adding conversions in a late push against Skolars in Week One. In Week Six, he inspired a depleted 11-man Tigers side to a memorable 28-18 win over Accra Panthers, last season’s third-place finishers. He is currently  the league’s top kicker with 26 conversions, underlining his reliability in front of the posts.</p>
<p>Announcing the award, RLFG officials highlighted Montchon’s all-round impact. “Kofi Montchon has been phenomenal throughout July. His vision as a standoff, his precision in conversions, and his ability to rise to the occasion when his team needs him most set him apart. This award is a recognition of his talent and hard work.”</p>
<p>Montchon now joins Kevin Boadu (Bulls, May winner) and Adam Marsuu (Accra Panthers, June winner) as Player of the Month recipients in the 2025 season.</p>
<p>Nungua Tigers are currently third on the league table and remain in strong contention for a playoff spot. With Montchon pulling the strings in attack, the club is well-placed to challenge in the weeks ahead.</p>', '/news/montchon_wide.jpeg', 'News', '{}'::text[], 'published', '2025-08-05'::timestamptz, '[{"type": "paragraph", "content": "Montchon, who plays at standoff, has been a driving force in the Tigers’ campaign, combining vision, game control, and accurate kicking to steer his team through key fixtures. His consistency and leadership earned him overwhelming support in the fan vote, making him the clear choice for the award."}, {"type": "image", "src": "/news/montchon.jpeg", "size": "contain"}, {"type": "paragraph", "content": "In July, Montchon produced standout performances, including scoring two tries and adding conversions in a late push against Skolars in Week One. In Week Six, he inspired a depleted 11-man Tigers side to a memorable 28-18 win over Accra Panthers, last season’s third-place finishers. He is currently  the league’s top kicker with 26 conversions, underlining his reliability in front of the posts."}, {"type": "paragraph", "content": "Announcing the award, RLFG officials highlighted Montchon’s all-round impact. “Kofi Montchon has been phenomenal throughout July. His vision as a standoff, his precision in conversions, and his ability to rise to the occasion when his team needs him most set him apart. This award is a recognition of his talent and hard work.”"}, {"type": "paragraph", "content": "Montchon now joins Kevin Boadu (Bulls, May winner) and Adam Marsuu (Accra Panthers, June winner) as Player of the Month recipients in the 2025 season."}, {"type": "paragraph", "content": "Nungua Tigers are currently third on the league table and remain in strong contention for a playoff spot. With Montchon pulling the strings in attack, the club is well-placed to challenge in the weeks ahead."}]'::jsonb),
  ('david-akomeah-appointed-ro-rlfg-board-for-2025-2027-term', 'David Akomeah Asokwah Appointed to Board of Rugby League Federation Ghana', 'In a decisive show of confidence and continuity, Mrs Juliana Storey has been re-elected as President of the Rugby League Federation Ghana (RLFG) following the Federation’s board elections held on Saturday, July 6, 2025.', '<p>In a strategic appointment that highlights the growing synergy between education and sport, David Akomeah Asokwah, District Director of Education for Afigya Kwabre South, has been named a board member of the Rugby League Federation Ghana (RLFG). His selection forms part of the Federation’s newly elected executive body for the 2025–2027 term, led by re-elected President Mrs. Juliana Storey.</p>
<img src="/news/appointment_2.jpeg" alt="">
<p>Mr. Asokwah’s appointment is a recognition of his instrumental role in advancing rugby league at the grassroots level, especially within the Ashanti Region, where he has led and coordinated regional rugby league tournaments over the past two years. His hands-on leadership and strong commitment to youth development through sport have made him a respected figure within both the education and sporting communities.</p>
<blockquote><p>Having Mr. Asokwah on our board strengthens our connection to the educational sector,” said RLFG President Juliana Storey. “He has been a consistent partner in developing the game in the Ashanti Region and shares our belief that rugby league can be a powerful tool for youth transformation</p><p><em>Mrs. Juliana Storey —  President - RLFG</em></p></blockquote>
<p>As District Director of Education, Mr. Asokwah has supported numerous initiatives to integrate rugby league into school sports programs, working closely with PE teachers, local clubs, and RLFG development officers. His efforts have introduced the game to hundreds of students and helped build competitive platforms for school teams across the region.</p>
<p>“For the past two years, I’ve witnessed how rugby league can positively shape character, discipline, and teamwork among students,” Mr. Asokwah said. “I’m honored to take on this national role and look forward to helping the sport grow across all regions, especially in our schools.”</p>
<p>Nana Adu Gyamfi’s unique position as both a traditional leader and business executive gives him the capacity to forge strong local and global partnerships, drive investment into the sport, and help promote rugby league within both urban centres and rural communities across the country.</p>
<p>With Mr. Asokwah now on the RLFG Board, the Federation reinforces its goal to make rugby league a nationwide, school-supported sport, while ensuring that education leaders play a central role in its expansion and sustainability.</p>', '/news/appointment_2.jpeg', 'News', '{}'::text[], 'published', '2025-07-16'::timestamptz, '[{"type": "paragraph", "content": "In a strategic appointment that highlights the growing synergy between education and sport, David Akomeah Asokwah, District Director of Education for Afigya Kwabre South, has been named a board member of the Rugby League Federation Ghana (RLFG). His selection forms part of the Federation’s newly elected executive body for the 2025–2027 term, led by re-elected President Mrs. Juliana Storey."}, {"type": "image", "src": "/news/appointment_2.jpeg", "size": "contain"}, {"type": "paragraph", "content": "Mr. Asokwah’s appointment is a recognition of his instrumental role in advancing rugby league at the grassroots level, especially within the Ashanti Region, where he has led and coordinated regional rugby league tournaments over the past two years. His hands-on leadership and strong commitment to youth development through sport have made him a respected figure within both the education and sporting communities."}, {"type": "quote", "preface": "", "content": "Having Mr. Asokwah on our board strengthens our connection to the educational sector,” said RLFG President Juliana Storey. “He has been a consistent partner in developing the game in the Ashanti Region and shares our belief that rugby league can be a powerful tool for youth transformation", "by": "Mrs. Juliana Storey", "image": "/team/12.png", "designation": " President - RLFG"}, {"type": "paragraph", "content": "As District Director of Education, Mr. Asokwah has supported numerous initiatives to integrate rugby league into school sports programs, working closely with PE teachers, local clubs, and RLFG development officers. His efforts have introduced the game to hundreds of students and helped build competitive platforms for school teams across the region."}, {"type": "paragraph", "content": "“For the past two years, I’ve witnessed how rugby league can positively shape character, discipline, and teamwork among students,” Mr. Asokwah said. “I’m honored to take on this national role and look forward to helping the sport grow across all regions, especially in our schools.”"}, {"type": "paragraph", "content": "Nana Adu Gyamfi’s unique position as both a traditional leader and business executive gives him the capacity to forge strong local and global partnerships, drive investment into the sport, and help promote rugby league within both urban centres and rural communities across the country."}, {"type": "paragraph", "content": "With Mr. Asokwah now on the RLFG Board, the Federation reinforces its goal to make rugby league a nationwide, school-supported sport, while ensuring that education leaders play a central role in its expansion and sustainability."}]'::jsonb),
  ('nana-adu-gyamfi-appointed-ro-rlfg-board-for-2025-2027-term', 'Nana Adu Gyamfi Kumanin Barima Kese I Appointed to RLFG Board for 2025–2027 Term', 'In a decisive show of confidence and continuity, Mrs Juliana Storey has been re-elected as President of the Rugby League Federation Ghana (RLFG) following the Federation’s board elections held on Saturday, July 6, 2025.', '<p>The Rugby League Federation Ghana (RLFG) has officially announced the appointment of Mr. George Morgan, also known in traditional leadership as Nana Adu Gyamfi Kumanin Barima Kese I, the Nkosuohene of Nyankyerenease in the Ashanti Region, to its Board for the 2025–2027 term.</p>
<img src="/news/appointment_1.jpeg" alt="">
<p>A respected entrepreneur and CEO of Shamore Herbal, Nana Adu Gyamfi brings a distinguished track record in business development, community leadership, and strategic partnerships. His commitment to youth empowerment, education, and public health in his traditional area aligns seamlessly with the RLFG’s mission to leverage rugby league as a platform for transformation and national development.</p>
<p>His appointment comes at a pivotal time in the sport’s evolution in Ghana. Rugby league is experiencing unprecedented growth at the grassroots, school, and national levels, and RLFG is actively building the structures to support long-term development, with a particular focus on youth engagement and women’s participation in sport.</p>
<blockquote><p>It is an honour to serve on the board of the Rugby League Federation Ghana,” said Nana Adu Gyamfi. “As someone passionate about development and youth empowerment, I see this sport as more than just a game — it’s a platform for discipline, unity, and opportunity for young Ghanaiaans</p><p><em>Nana Adu Gyamfi Kumanin Barima Kese I — Board Member</em></p></blockquote>
<p>Nana Adu Gyamfi’s unique position as both a traditional leader and business executive gives him the capacity to forge strong local and global partnerships, drive investment into the sport, and help promote rugby league within both urban centres and rural communities across the country.</p>
<p>RLFG President Mrs. Juliana Storey welcomed the appointment, describing it as a strategic step forward for the federation:</p>
<p>“We are excited to have Nana Adu Gyamfi Kumanin Barima Kese 1 join the board. His vision and experience align with our goals for the sport’s growth, and his presence reflects our strong desire to grow rugby league in all parts of Ghana with the best people by our side.”</p>
<p>Nana Adu Gyamfi joins the board at a time when Ghana is preparing to host a series of high-profile international fixtures — including the Ghana-Nigeria test series in October, and the historic Tri-Nation Series in November, which will feature Nigeria and the ROOTS Rugby Family. His voice on the board will be instrumental in guiding RLFG through this new chapter of local consolidation and international engagement.</p>
<p>With Nana Adu Gyamfi now among its leadership, the Rugby League Federation Ghana is well-positioned to deepen its national impact, strengthen community ties, and usher in a new era of inclusion, pride, and global visibility for rugby league in Ghana.</p>', '/news/appointment_1.jpeg', 'News', '{}'::text[], 'published', '2025-07-14'::timestamptz, '[{"type": "paragraph", "content": "The Rugby League Federation Ghana (RLFG) has officially announced the appointment of Mr. George Morgan, also known in traditional leadership as Nana Adu Gyamfi Kumanin Barima Kese I, the Nkosuohene of Nyankyerenease in the Ashanti Region, to its Board for the 2025–2027 term."}, {"type": "image", "src": "/news/appointment_1.jpeg", "size": "contain"}, {"type": "paragraph", "content": "A respected entrepreneur and CEO of Shamore Herbal, Nana Adu Gyamfi brings a distinguished track record in business development, community leadership, and strategic partnerships. His commitment to youth empowerment, education, and public health in his traditional area aligns seamlessly with the RLFG’s mission to leverage rugby league as a platform for transformation and national development."}, {"type": "paragraph", "content": "His appointment comes at a pivotal time in the sport’s evolution in Ghana. Rugby league is experiencing unprecedented growth at the grassroots, school, and national levels, and RLFG is actively building the structures to support long-term development, with a particular focus on youth engagement and women’s participation in sport."}, {"type": "quote", "preface": "", "content": "It is an honour to serve on the board of the Rugby League Federation Ghana,” said Nana Adu Gyamfi. “As someone passionate about development and youth empowerment, I see this sport as more than just a game — it’s a platform for discipline, unity, and opportunity for young Ghanaiaans", "by": "Nana Adu Gyamfi Kumanin Barima Kese I", "image": null, "designation": "Board Member"}, {"type": "paragraph", "content": "Nana Adu Gyamfi’s unique position as both a traditional leader and business executive gives him the capacity to forge strong local and global partnerships, drive investment into the sport, and help promote rugby league within both urban centres and rural communities across the country."}, {"type": "paragraph", "content": "RLFG President Mrs. Juliana Storey welcomed the appointment, describing it as a strategic step forward for the federation:"}, {"type": "paragraph", "content": "“We are excited to have Nana Adu Gyamfi Kumanin Barima Kese 1 join the board. His vision and experience align with our goals for the sport’s growth, and his presence reflects our strong desire to grow rugby league in all parts of Ghana with the best people by our side.”"}, {"type": "paragraph", "content": "Nana Adu Gyamfi joins the board at a time when Ghana is preparing to host a series of high-profile international fixtures — including the Ghana-Nigeria test series in October, and the historic Tri-Nation Series in November, which will feature Nigeria and the ROOTS Rugby Family. His voice on the board will be instrumental in guiding RLFG through this new chapter of local consolidation and international engagement."}, {"type": "paragraph", "content": "With Nana Adu Gyamfi now among its leadership, the Rugby League Federation Ghana is well-positioned to deepen its national impact, strengthen community ties, and usher in a new era of inclusion, pride, and global visibility for rugby league in Ghana."}]'::jsonb),
  ('juliana-storey-re-elected-president-of-rlfg', 'Juliana Storey Re-Elected President of Rugby League Federation Ghana', 'In a decisive show of confidence and continuity, Mrs Juliana Storey has been re-elected as President of the Rugby League Federation Ghana (RLFG) following the Federation’s board elections held on Saturday, July 6, 2025.', '<p>An accomplished education consultant, Madam Storey has been instrumental in the rapid rise of rugby league across Ghana. Under her stewardship over the past two years, the Federation has witnessed significant milestones — from expanding grassroots participation and organizing nationwide tournaments, to delivering coaching and officiating courses and deepening strategic partnerships with local and international stakeholders.</p>
<blockquote><p>Speaking after her re-election, Madam Storey conveyed deep appreciation for the mandate given her to lead once again.</p><p>This is a moment of renewed purpose. Rugby league in Ghana has come a long way, but there is much more ahead. Together with the newly elected board, I am committed to growing the game, developing our youth, and taking Ghana to the world stage</p><p><em>Mrs. Juliana Storey —  President - RLFG</em></p></blockquote>
<p>[{&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/juli_two.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/juli_four.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/juli_three.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/juli_five.jpeg&#x27;}]</p>
<hr>
<h1>A New Era of Leadership and Opportunity</h1>
<p>The new RLFG Board, elected to serve from July 2025 to July 2027, features a dynamic blend of professionals with expertise spanning education, finance, corporate leadership, and sports management. The board members are:</p>
<p>Juliana Storey – Educational Consultant (President), Daniel Oko Djanie – Events, Brands and Marketing professional (Vice President), Rob Oram – CEO, Hapag-Lloyd (Treasurer), George Morgan – CEO, Shamore Herbal (Ghana), David Akomeah Asokwah – District Director of Education, Afigya Kwabre South, Ekua Ofori – Legal and Governance, Hubert Leo-Mensah – Sports Management Consultant.</p>
<img src="/news/new_board.jpeg" alt="">
<hr>
<p>The Federation’s renewed leadership is expected to advance key priorities, including youth development, regional expansion, enhanced women’s participation, and international competitiveness. The re-election of Madam Storey signals stability, vision, and an unrelenting drive to position Ghana as a formidable force in global rugby league.</p>
<p>As the RLFG charts its path forward, all eyes are on the Federation to lead with integrity, ambition, and unity — embodying the values of the sport and the aspirations of a new generation of Ghanaian athletes- Remond Safi (Regional Manager, Middle East and Africa Rugby League)</p>', '/news/juli_one.jpeg', 'News', '{}'::text[], 'published', '2025-07-08'::timestamptz, '[{"type": "paragraph", "content": "An accomplished education consultant, Madam Storey has been instrumental in the rapid rise of rugby league across Ghana. Under her stewardship over the past two years, the Federation has witnessed significant milestones — from expanding grassroots participation and organizing nationwide tournaments, to delivering coaching and officiating courses and deepening strategic partnerships with local and international stakeholders."}, {"type": "quote", "preface": "Speaking after her re-election, Madam Storey conveyed deep appreciation for the mandate given her to lead once again.", "content": "This is a moment of renewed purpose. Rugby league in Ghana has come a long way, but there is much more ahead. Together with the newly elected board, I am committed to growing the game, developing our youth, and taking Ghana to the world stage", "by": "Mrs. Juliana Storey", "image": "/team/12.png", "designation": " President - RLFG"}, {"type": "gallery", "content": [{"type": "image", "src": "/news/juli_two.jpeg"}, {"type": "image", "src": "/news/juli_four.jpeg"}, {"type": "image", "src": "/news/juli_three.jpeg"}, {"type": "image", "src": "/news/juli_five.jpeg"}]}, {"type": "spacer"}, {"type": "heading", "content": "A New Era of Leadership and Opportunity", "attrs": {"level": "one", "decoration": "bold"}}, {"type": "paragraph", "content": "The new RLFG Board, elected to serve from July 2025 to July 2027, features a dynamic blend of professionals with expertise spanning education, finance, corporate leadership, and sports management. The board members are:"}, {"type": "paragraph", "content": "Juliana Storey – Educational Consultant (President), Daniel Oko Djanie – Events, Brands and Marketing professional (Vice President), Rob Oram – CEO, Hapag-Lloyd (Treasurer), George Morgan – CEO, Shamore Herbal (Ghana), David Akomeah Asokwah – District Director of Education, Afigya Kwabre South, Ekua Ofori – Legal and Governance, Hubert Leo-Mensah – Sports Management Consultant."}, {"type": "image", "src": "/news/new_board.jpeg", "size": "contain"}, {"type": "spacer"}, {"type": "paragraph", "content": "The Federation’s renewed leadership is expected to advance key priorities, including youth development, regional expansion, enhanced women’s participation, and international competitiveness. The re-election of Madam Storey signals stability, vision, and an unrelenting drive to position Ghana as a formidable force in global rugby league."}, {"type": "paragraph", "content": "As the RLFG charts its path forward, all eyes are on the Federation to lead with integrity, ambition, and unity — embodying the values of the sport and the aspirations of a new generation of Ghanaian athletes- Remond Safi (Regional Manager, Middle East and Africa Rugby League)"}]'::jsonb),
  ('rlfg-engages-ayawaso-west-municipal-assembly-on-strategic-sports-development-initiative', 'RLFG Engages Ayawaso West Municipal Assembly on Strategic Sports Development Initiative', 'The Rugby League Federation Ghana (RLFG), led by General Manager Jafaru Awudu Mustapha, participated in the Second Quarter Meeting of the Sports and Recreational Development Sub-Committee of the Ayawaso West Municipal Assembly, to present and discuss the introduction of rugby league within the Municipality.', '<p>The RLFG delegation included Elizabeth Adongo, Finance Officer, and Hilaria Wuaku, Communications Lead. The meeting, held at the Assembly Hall, brought together key stakeholders focused on developing inclusive and sustainable sports programs within Ayawaso West.</p>
<p>As part of the agenda, the RLFG General Manager briefed the committee on the Federation’s background, milestones, and vision for nationwide grassroots engagement through rugby league. He outlined strategic plans to introduce the sport into schools, communities, and youth development centres in the municipality.</p>
<p>[{&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/ayawaso_one.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/ayawaso_two.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/ayawaso_three.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/ayawaso_four.jpeg&#x27;}]</p>
<p>“Rugby league is more than just a sport—it is a tool for community building, character development, and opportunity creation,” said Jafaru Awudu Mustapha, General Manager of RLFG. “Partnering with municipal assemblies like Ayawaso West is essential to reaching the grassroots and building a strong foundation.”</p>
<p>The presentation was met with enthusiasm and interest from committee members, who acknowledged the sport’s potential to contribute to holistic youth development.</p>
<p>“The Rugby League Federation Ghana has demonstrated a clear and thoughtful strategy for engaging young people through sport,” said Mr. James Odoi Wilson, Head of Sports at the Ayawaso West Municipal Assembly. “As a Municipality, we are committed to supporting initiatives that empower the next generation, and rugby league aligns well with that mission.”</p>
<p>The Chairman of the meeting, Hon. David Kofi Sparks Anorlejamah, praised the RLFG’s approach and reaffirmed the Assembly&#x27;s interest in collaborative action.</p>
<p>“This is a necessary and timely conversation,” the Chairman remarked. “The Assembly welcomes partnerships like this that promote sports as a development tool, and we look forward to working closely with the Federation to bring this to life within Ayawaso West.”</p>
<p>With the introduction and roll-out of rugby league within the municipality now underway, the RLFG anticipates further engagements with local leaders and stakeholders, ensuring that schools and communities benefit directly from structured sports programs.</p>', '/news/ayawaso_five.jpeg', 'News', '{}'::text[], 'published', '2025-06-25'::timestamptz, '[{"type": "paragraph", "content": "The RLFG delegation included Elizabeth Adongo, Finance Officer, and Hilaria Wuaku, Communications Lead. The meeting, held at the Assembly Hall, brought together key stakeholders focused on developing inclusive and sustainable sports programs within Ayawaso West."}, {"type": "paragraph", "content": "As part of the agenda, the RLFG General Manager briefed the committee on the Federation’s background, milestones, and vision for nationwide grassroots engagement through rugby league. He outlined strategic plans to introduce the sport into schools, communities, and youth development centres in the municipality."}, {"type": "gallery", "content": [{"type": "image", "src": "/news/ayawaso_one.jpeg"}, {"type": "image", "src": "/news/ayawaso_two.jpeg"}, {"type": "image", "src": "/news/ayawaso_three.jpeg"}, {"type": "image", "src": "/news/ayawaso_four.jpeg"}]}, {"type": "paragraph", "content": "“Rugby league is more than just a sport—it is a tool for community building, character development, and opportunity creation,” said Jafaru Awudu Mustapha, General Manager of RLFG. “Partnering with municipal assemblies like Ayawaso West is essential to reaching the grassroots and building a strong foundation.”"}, {"type": "paragraph", "content": "The presentation was met with enthusiasm and interest from committee members, who acknowledged the sport’s potential to contribute to holistic youth development."}, {"type": "paragraph", "content": "“The Rugby League Federation Ghana has demonstrated a clear and thoughtful strategy for engaging young people through sport,” said Mr. James Odoi Wilson, Head of Sports at the Ayawaso West Municipal Assembly. “As a Municipality, we are committed to supporting initiatives that empower the next generation, and rugby league aligns well with that mission.”"}, {"type": "paragraph", "content": "The Chairman of the meeting, Hon. David Kofi Sparks Anorlejamah, praised the RLFG’s approach and reaffirmed the Assembly''s interest in collaborative action."}, {"type": "paragraph", "content": "“This is a necessary and timely conversation,” the Chairman remarked. “The Assembly welcomes partnerships like this that promote sports as a development tool, and we look forward to working closely with the Federation to bring this to life within Ayawaso West.”"}, {"type": "paragraph", "content": "With the introduction and roll-out of rugby league within the municipality now underway, the RLFG anticipates further engagements with local leaders and stakeholders, ensuring that schools and communities benefit directly from structured sports programs."}]'::jsonb),
  ('rlfg-celebrates-active-fatherhood-with-legacy-in-motion-2.0', 'RLFG Celebrates Active Fatherhood with ''Legacy'' in Motion 2.0', 'In a refreshing departure from the usual neckties-and-sermons Father’s Day tradition, the Rugby League Federation Ghana (RLFG) delivered a vibrant, action-packed celebration that placed fathers at the heart of the game—literally.', '<p>Dubbed Legacy in Motion 2.0, the second edition of RLFG’s flagship Father’s Day event transformed the federation’s grounds in Accra into a living tribute to fatherhood, filled with sport, wellness, and joy. Fathers didn’t just attend—they played, bonded, competed, and took center stage in front of their families and fans.</p>
<p>The highlight of the day was the much-anticipated rugby league showdown between the Over 30s and Under 30s men—a spirited generational clash that saw the younger team triumph 40–4. But for many, it was the sight of veteran fathers lacing up their boots, charging down the field, and laughing with teammates that truly stole the show.</p>
<p>“Last year was nice, but this year was even better,” said Mr. Paul Alibah, father of RLFG Greater Accra Regional Coordinator Riddick Alibah. “Spending time with the boys, seeing how the sport has grown, and just being a part of it—it’s been the highlight of my year. I hope next year, even more fathers join us, so us old men can also run around, race, and feel young again.”</p>
<p>“I truly appreciate all the members of the Rugby League Federation Ghana for putting together such a beautiful Father’s Day event. I told my wife I really felt the spirit of Father’s Day this year—thanks to the rugby league family. It was my very first Father’s Day, and it felt incredibly special,” said Abdulrahman Moussa.</p>
<p>[{&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/legacy_one.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/legacy_three.jpeg&#x27;}]</p>
<p>But the match was just the beginning. RLFG reimagined Father’s Day as a full-blown family fair, complete with free health screenings, bouncy castles, board games, and an esports gaming zone powered by the Esports Association Ghana. Fathers—often sidelined on days like these—became front-and-center participants.</p>
<p>“This is what modern sport should look like—promoting wellness alongside competition,” said Riddick Alibah. “It’s not just about the game. It’s about recognizing fathers as leaders in their families and communities.”</p>
<p>One of the most talked-about highlights of the day was the Polytank Ice Bath Challenge, where players from both teams plunged into freezing tubs side by side. It was a true test of toughness and endurance—but also a powerful snapshot of camaraderie, laughter, and resilience: traits that embody fatherhood.</p>
<p>The family-friendly atmosphere was matched by strong inclusivity. A thrilling women’s exhibition match drew enthusiastic cheers as female athletes displayed skill, passion, and determination. That message of inclusivity extended to the officiating, with all matches led by an all-female team. Center referee Jackqueline Ansah was flanked by touch judges Jennifer Teiko Moncar and Elizabeth Adongo, with Adiza Mohammed and Angela Yakubu serving as table officials. Their confident handling of the game won praise from all corners.</p>
<p>“We are proud of the women who participated and showed that rugby league is a game for everyone,” said RLFG President Madam Juliana Storey. “Their courage and energy reflect our mission of making rugby league truly inclusive.”</p>
<p>The event also drew support from Ghana’s broader sporting community. The Spintex Knights, Ghana’s premier basketball team, and the Ghana KhoKho Federation joined as co-organizers—adding momentum, solidarity, and cross-sport excitement to the celebration.</p>
<p>[{&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/legacy_four.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/legacy_five.jpeg&#x27;}]</p>
<p>As the music faded and the fields cleared, RLFG’s message was clear—Legacy in Motion is more than a celebration. It’s a declaration.</p>
<p>“Legacy in Motion is not just an event,” said Mr. Marshall Nortey, RLFG Technical Manager. “It’s a platform to showcase the central role of fathers—not just as providers, but as active, joyful pillars of our families and communities. We’re building a tradition that honors that legacy—which is always in motion.”</p>
<p>With Legacy in Motion 3.0 already in the pipeline for 2026, RLFG has set a new standard for how Father’s Day is celebrated in Ghana—and it’s only going to get bigger.</p>', '/news/legacy_two.jpeg', 'News', '{}'::text[], 'published', '2025-06-15'::timestamptz, '[{"type": "paragraph", "content": "Dubbed Legacy in Motion 2.0, the second edition of RLFG’s flagship Father’s Day event transformed the federation’s grounds in Accra into a living tribute to fatherhood, filled with sport, wellness, and joy. Fathers didn’t just attend—they played, bonded, competed, and took center stage in front of their families and fans."}, {"type": "paragraph", "content": "The highlight of the day was the much-anticipated rugby league showdown between the Over 30s and Under 30s men—a spirited generational clash that saw the younger team triumph 40–4. But for many, it was the sight of veteran fathers lacing up their boots, charging down the field, and laughing with teammates that truly stole the show."}, {"type": "paragraph", "content": "“Last year was nice, but this year was even better,” said Mr. Paul Alibah, father of RLFG Greater Accra Regional Coordinator Riddick Alibah. “Spending time with the boys, seeing how the sport has grown, and just being a part of it—it’s been the highlight of my year. I hope next year, even more fathers join us, so us old men can also run around, race, and feel young again.”"}, {"type": "paragraph", "content": "“I truly appreciate all the members of the Rugby League Federation Ghana for putting together such a beautiful Father’s Day event. I told my wife I really felt the spirit of Father’s Day this year—thanks to the rugby league family. It was my very first Father’s Day, and it felt incredibly special,” said Abdulrahman Moussa."}, {"type": "gallery", "content": [{"type": "image", "src": "/news/legacy_one.jpeg"}, {"type": "image", "src": "/news/legacy_three.jpeg"}]}, {"type": "paragraph", "content": "But the match was just the beginning. RLFG reimagined Father’s Day as a full-blown family fair, complete with free health screenings, bouncy castles, board games, and an esports gaming zone powered by the Esports Association Ghana. Fathers—often sidelined on days like these—became front-and-center participants."}, {"type": "paragraph", "content": "“This is what modern sport should look like—promoting wellness alongside competition,” said Riddick Alibah. “It’s not just about the game. It’s about recognizing fathers as leaders in their families and communities.”"}, {"type": "paragraph", "content": "One of the most talked-about highlights of the day was the Polytank Ice Bath Challenge, where players from both teams plunged into freezing tubs side by side. It was a true test of toughness and endurance—but also a powerful snapshot of camaraderie, laughter, and resilience: traits that embody fatherhood."}, {"type": "paragraph", "content": "The family-friendly atmosphere was matched by strong inclusivity. A thrilling women’s exhibition match drew enthusiastic cheers as female athletes displayed skill, passion, and determination. That message of inclusivity extended to the officiating, with all matches led by an all-female team. Center referee Jackqueline Ansah was flanked by touch judges Jennifer Teiko Moncar and Elizabeth Adongo, with Adiza Mohammed and Angela Yakubu serving as table officials. Their confident handling of the game won praise from all corners."}, {"type": "paragraph", "content": "“We are proud of the women who participated and showed that rugby league is a game for everyone,” said RLFG President Madam Juliana Storey. “Their courage and energy reflect our mission of making rugby league truly inclusive.”"}, {"type": "paragraph", "content": "The event also drew support from Ghana’s broader sporting community. The Spintex Knights, Ghana’s premier basketball team, and the Ghana KhoKho Federation joined as co-organizers—adding momentum, solidarity, and cross-sport excitement to the celebration."}, {"type": "gallery", "content": [{"type": "image", "src": "/news/legacy_four.jpeg"}, {"type": "image", "src": "/news/legacy_five.jpeg"}]}, {"type": "paragraph", "content": "As the music faded and the fields cleared, RLFG’s message was clear—Legacy in Motion is more than a celebration. It’s a declaration."}, {"type": "paragraph", "content": "“Legacy in Motion is not just an event,” said Mr. Marshall Nortey, RLFG Technical Manager. “It’s a platform to showcase the central role of fathers—not just as providers, but as active, joyful pillars of our families and communities. We’re building a tradition that honors that legacy—which is always in motion.”"}, {"type": "paragraph", "content": "With Legacy in Motion 3.0 already in the pipeline for 2026, RLFG has set a new standard for how Father’s Day is celebrated in Ghana—and it’s only going to get bigger."}]'::jsonb),
  ('roots-rugby-family-set-for-historic-ghana-tour-in-november-2025', 'ROOTS Rugby Family Set for Historic Ghana Tour in November 2025', 'An unforgettable homecoming of culture, competition, and connection.', '<p>In a landmark moment for international rugby league and cultural exchange, the ROOTS Rugby Family will tour Ghana from November 23–30, 2025, for a week-long celebration of sport, heritage, and unity. The tour will feature a series of matches and development programs aimed at strengthening ties between the African diaspora and the continent.</p>
<p>During the tour, ROOTS Rugby Family’s men’s and women’s teams will each play three high-profile matches against Ghana’s national sides. In addition to the on-field action, the ROOTS delegation will engage in community development, youth outreach, and knowledge-sharing sessions with local coaches and players.</p>
<blockquote><p>Tiana Granby, President of ROOTS Rugby Family, shared her excitement about the upcoming visit:</p><p>ROOTS Rugby Family is honored to journey to Ghana this November to compete against the national men’s and women’s rugby league teams in a celebration of culture, sport, and unity. This historic tour represents more than just rugby league—it is a powerful homecoming that strengthens the deep-rooted connections between the African diaspora and the continent. Through these matches, we aim to forge lasting bonds of brotherhood, sisterhood, and shared purpose. We look forward to an unforgettable experience rooted in heritage, competition, and mutual respect.</p><p><em>Tiana Granby —  President - ROOTS Rugby Family</em></p></blockquote>
<p>[{&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/roots_2.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/roots_3.jpeg&#x27;}]</p>
<p>ROOTS Rugby Family is globally recognized for its mission to empower athletes of African descent through sport and community. This tour represents both a symbolic and practical return to their roots, bringing together players, coaches, and administrators from across the diaspora to connect with their heritage in Ghana.</p>
<p>The Rugby League Federation Ghana (RLFG) has expressed pride in hosting this milestone event, which aligns with its broader mission to use rugby league as a platform for youth development, cultural exchange, and global solidarity.</p>
<blockquote><p>The President of the Rugby League Federation Ghana, Madam Juliana Storey, also expressed her excitement about this milestone:</p><p>We are deeply honored to welcome the ROOTS Rugby Family to Ghana. This tour is a celebration of shared identity, unity, and the enduring strength of the global African family. We look forward to unforgettable matches, lasting friendships, and the continued growth of rugby league in Ghana and beyond.</p><p><em>Mrs. Juliana Storey —  President - RLFG</em></p></blockquote>
<p>Beyond the pitch, the tour will include training clinics, school visits, and collaborative workshops that engage grassroots players and local communities. These initiatives are expected to leave a lasting legacy on Ghana’s rugby league landscape and strengthen long-term partnerships.</p>
<p>As Ghana continues to develop the sport and prepare for future international competitions, landmark initiatives like the ROOTS Rugby Family tour highlight the power of rugby league to blend sport with purpose.</p>', '/news/roots_story_cover.jpeg', 'News', '{}'::text[], 'published', '2025-06-04'::timestamptz, '[{"type": "paragraph", "content": "In a landmark moment for international rugby league and cultural exchange, the ROOTS Rugby Family will tour Ghana from November 23–30, 2025, for a week-long celebration of sport, heritage, and unity. The tour will feature a series of matches and development programs aimed at strengthening ties between the African diaspora and the continent."}, {"type": "paragraph", "content": "During the tour, ROOTS Rugby Family’s men’s and women’s teams will each play three high-profile matches against Ghana’s national sides. In addition to the on-field action, the ROOTS delegation will engage in community development, youth outreach, and knowledge-sharing sessions with local coaches and players."}, {"type": "quote", "preface": "Tiana Granby, President of ROOTS Rugby Family, shared her excitement about the upcoming visit:", "content": "ROOTS Rugby Family is honored to journey to Ghana this November to compete against the national men’s and women’s rugby league teams in a celebration of culture, sport, and unity. This historic tour represents more than just rugby league—it is a powerful homecoming that strengthens the deep-rooted connections between the African diaspora and the continent. Through these matches, we aim to forge lasting bonds of brotherhood, sisterhood, and shared purpose. We look forward to an unforgettable experience rooted in heritage, competition, and mutual respect.", "by": "Tiana Granby", "image": null, "designation": " President - ROOTS Rugby Family"}, {"type": "gallery", "content": [{"type": "image", "src": "/news/roots_2.jpeg"}, {"type": "image", "src": "/news/roots_3.jpeg"}]}, {"type": "paragraph", "content": "ROOTS Rugby Family is globally recognized for its mission to empower athletes of African descent through sport and community. This tour represents both a symbolic and practical return to their roots, bringing together players, coaches, and administrators from across the diaspora to connect with their heritage in Ghana."}, {"type": "paragraph", "content": "The Rugby League Federation Ghana (RLFG) has expressed pride in hosting this milestone event, which aligns with its broader mission to use rugby league as a platform for youth development, cultural exchange, and global solidarity."}, {"type": "quote", "preface": "The President of the Rugby League Federation Ghana, Madam Juliana Storey, also expressed her excitement about this milestone:", "content": "We are deeply honored to welcome the ROOTS Rugby Family to Ghana. This tour is a celebration of shared identity, unity, and the enduring strength of the global African family. We look forward to unforgettable matches, lasting friendships, and the continued growth of rugby league in Ghana and beyond.", "by": "Mrs. Juliana Storey", "image": "/team/12.png", "designation": " President - RLFG"}, {"type": "paragraph", "content": "Beyond the pitch, the tour will include training clinics, school visits, and collaborative workshops that engage grassroots players and local communities. These initiatives are expected to leave a lasting legacy on Ghana’s rugby league landscape and strengthen long-term partnerships."}, {"type": "paragraph", "content": "As Ghana continues to develop the sport and prepare for future international competitions, landmark initiatives like the ROOTS Rugby Family tour highlight the power of rugby league to blend sport with purpose."}]'::jsonb),
  ('rlfg-launch-strategic-five-year-plan-from-2025-to-2030', 'Igniting the Game - Rugby League Federation Ghana Launch Strategic Plan for 2025-2030', 'As the season opener kicked off at the University of Ghana Rugby League Stadium on Sunday, May 11, the RLFG Board also presented its ambitious five-year strategic plan to grow the sport of rugby league across Accra and beyond.   ', '<p>The &#x27;Igniting the Game&#x27; Strategy focuses on five key pillars that will act as the catalyst for growth throughout Ghana up to 2030: Participation, Performance, Workforce and People, Competition, and Engagement.</p>
<p>These pillars are designed to support our current stakeholders and communities while also attracting new audiences, aligning new partners, and welcoming anyone who wishes to join our mission of ensuring rugby league thrives throughout the country.</p>
<img src="/news/strategy_content.jpeg" alt="">
<blockquote><p>Madam Juliana Storey, President of the Rugby League Federation Ghana, commented on the strategy’s publication</p><p>Igniting the Game is an exciting new era for the RLFG and the sport in Ghana. Although ambitious in our targets, we are also realistic that tripling our metrics, aiming to be the number one rugby league playing nation in Africa and excelling in our stakeholder management will not be easy. The focus of the strategy however, will remain wrapped around our people and the workforce who bring our game to life day in and day out. From the medical teams supporting our players in the field, to the teachers and coaches present in our schools and communities, and the administrators who make all activity possible, we have ensured a whole community approach — wanting all who join us on our journey to feel welcome, and to be recognised for playing their part. Importantly, we aspire to cement the legacy of those who have brought us to this point whilst inspiring the next generation of Ghanaian-based rugby league champions</p><p><em>Mrs. Juliana Storey —  President - RLFG</em></p></blockquote>
<p>For a snapshot of the strategy, you can access our visual document using the link below</p>
<p><a href="https://drive.google.com/file/d/1vQu89LdU-sWfvzix6THfHsEEmMDIqJKU/view?usp=sharing">View Visual Document</a></p>
<p>As we mark our 13th year of activity, we are proud to share a vision that clearly maps the future of rugby league in Ghana. We welcome potential stakeholders to reach out if you would like to get involved or simply learn more, as we truly aim to Ignite the Game across our great nation.</p>', '/news/strategy.jpeg', 'News', '{}'::text[], 'published', '2025-05-20'::timestamptz, '[{"type": "paragraph", "content": "The ''Igniting the Game'' Strategy focuses on five key pillars that will act as the catalyst for growth throughout Ghana up to 2030: Participation, Performance, Workforce and People, Competition, and Engagement."}, {"type": "paragraph", "content": "These pillars are designed to support our current stakeholders and communities while also attracting new audiences, aligning new partners, and welcoming anyone who wishes to join our mission of ensuring rugby league thrives throughout the country."}, {"type": "image", "src": "/news/strategy_content.jpeg", "size": "contain"}, {"type": "quote", "preface": "Madam Juliana Storey, President of the Rugby League Federation Ghana, commented on the strategy’s publication", "content": "Igniting the Game is an exciting new era for the RLFG and the sport in Ghana. Although ambitious in our targets, we are also realistic that tripling our metrics, aiming to be the number one rugby league playing nation in Africa and excelling in our stakeholder management will not be easy. The focus of the strategy however, will remain wrapped around our people and the workforce who bring our game to life day in and day out. From the medical teams supporting our players in the field, to the teachers and coaches present in our schools and communities, and the administrators who make all activity possible, we have ensured a whole community approach — wanting all who join us on our journey to feel welcome, and to be recognised for playing their part. Importantly, we aspire to cement the legacy of those who have brought us to this point whilst inspiring the next generation of Ghanaian-based rugby league champions", "by": "Mrs. Juliana Storey", "image": "/team/12.png", "designation": " President - RLFG"}, {"type": "paragraph", "content": "For a snapshot of the strategy, you can access our visual document using the link below"}, {"type": "link", "content": "https://drive.google.com/file/d/1vQu89LdU-sWfvzix6THfHsEEmMDIqJKU/view?usp=sharing", "attrs": {"display_as": "button", "text": "View Visual Document"}}, {"type": "paragraph", "content": "As we mark our 13th year of activity, we are proud to share a vision that clearly maps the future of rugby league in Ghana. We welcome potential stakeholders to reach out if you would like to get involved or simply learn more, as we truly aim to Ignite the Game across our great nation."}]'::jsonb),
  ('three-erl-level-1-coach-accreditation', 'Three Earn ERL Level 1 Coach Accreditation: A Milestone for Rugby League in Ghana', 'The Rugby League Federation Ghana is proud to announce that Hilaria Wuaku, Riddick Alibah, and George Asamoah have successfully earned their ERL Level 1 Coach Accreditation after completing the coaching course and all post-course requirements.', '<p>This achievement signifies a significant step forward for rugby league in Ghana, as these newly accredited coaches are now equipped to develop and nurture the next generation of talent, contributing to the sport’s growth and sustainability in the country.</p>
<blockquote><p>Speaking on the achievement, Jafaru Awudu Mustapha, the course educator and Salford Rugby League Development Manager, praised the trio for their dedication and commitment:</p><p>The hard work and enthusiasm shown by Hilaria, Riddick, and George throughout the  period were exceptional. They’ve demonstrated the qualities of effective coaches—passion, discipline, and the ability to inspire others. I have no doubt they’ll make a positive impact on rugby league development in Ghana.</p><p><em>Jafaru Awudu Mustapha — General Manager - RLFG</em></p></blockquote>
<blockquote><p>The President of the Rugby League Federation Ghana, Madam Juliana Storey, also expressed her excitement about this milestone:</p><p>This is a proud moment for the Federation and for Ghana. Hilaria, Riddick, and George’s achievement highlights our continuous effort to build capacity and create opportunities for rugby league enthusiasts. As we look to expand the sport across the country, their contributions as coaches will be invaluable.</p><p><em>Mrs. Juliana Storey —  President - RLFG</em></p></blockquote>
<p>The newly accredited coaches join a growing community of professionals dedicated to promoting rugby league in Ghana with Hilaria Wuaku being the first female in Ghana to be accredited. Their journey is not just a personal accomplishment but also a testament to the Federation’s vision of developing grassroots rugby league and establishing Ghana as a formidable force in the sport.</p>
<p>Congratulations to Hilaria, Riddick, and George for this remarkable achievement. The Rugby League Federation Ghana looks forward to seeing the transformative impact they will have on players and the sport as a whole.</p>', '/news/refs_cover.jpeg', 'competitions', array['News', 'Accreditation']::text[], 'published', '2024-12-07'::timestamptz, '[{"type": "paragraph", "content": "This achievement signifies a significant step forward for rugby league in Ghana, as these newly accredited coaches are now equipped to develop and nurture the next generation of talent, contributing to the sport’s growth and sustainability in the country."}, {"type": "quote", "preface": "Speaking on the achievement, Jafaru Awudu Mustapha, the course educator and Salford Rugby League Development Manager, praised the trio for their dedication and commitment:", "content": "The hard work and enthusiasm shown by Hilaria, Riddick, and George throughout the  period were exceptional. They’ve demonstrated the qualities of effective coaches—passion, discipline, and the ability to inspire others. I have no doubt they’ll make a positive impact on rugby league development in Ghana.", "by": "Jafaru Awudu Mustapha", "image": "/team/2.png", "designation": "General Manager - RLFG"}, {"type": "quote", "preface": "The President of the Rugby League Federation Ghana, Madam Juliana Storey, also expressed her excitement about this milestone:", "content": "This is a proud moment for the Federation and for Ghana. Hilaria, Riddick, and George’s achievement highlights our continuous effort to build capacity and create opportunities for rugby league enthusiasts. As we look to expand the sport across the country, their contributions as coaches will be invaluable.", "by": "Mrs. Juliana Storey", "image": "/team/12.png", "designation": " President - RLFG"}, {"type": "paragraph", "content": "The newly accredited coaches join a growing community of professionals dedicated to promoting rugby league in Ghana with Hilaria Wuaku being the first female in Ghana to be accredited. Their journey is not just a personal accomplishment but also a testament to the Federation’s vision of developing grassroots rugby league and establishing Ghana as a formidable force in the sport."}, {"type": "paragraph", "content": "Congratulations to Hilaria, Riddick, and George for this remarkable achievement. The Rugby League Federation Ghana looks forward to seeing the transformative impact they will have on players and the sport as a whole."}]'::jsonb),
  ('president-cup-2024-a-thrilling-showdown-of-rugby-talent', 'President’s Cup 2024: A Thrilling Showdown of Rugby League Talent', 'The 2024 President’s Cup, an annual showcase of Ghana’s finest rugby league talent, took center stage on Sunday, November 24, 2024 at the University of Ghana Rugby Stadium. The event brought together players from Greater Accra, Central, and Ashanti Regions, offering a vibrant display of skill, determination, and the growing impact of rugby league in Ghana.', '<p>This year’s event was particularly significant as it celebrated Mrs. Juliana Storey, the first female president of the Rugby League Federation Ghana (RLFG). Under her leadership, the sport continues to gain momentum, and her vision for elevating rugby league to new heights was celebrated throughout the day.</p>
<p>In its fourth year, the President’s Cup, which debuted in 2021, has evolved into a multi-division competition featuring men’s, women’s, and boys’ teams. Over 100 players from various communities, senior and junior high schools participated in this year’s event, further highlighting the sport’s grassroots development.</p>
<hr>
<h1>U19 Boys: National Team Dominates the Day</h1>
<p>The day opened with a clash between the U19 Boys’ National Team and the President’s Team, comprising young talents from Awutu Winton SHS, Pentecost SHS, Aduman SHS, St. Michael SHS, and Akrofrom JHS. The National Team showcased their strength with a commanding 26-6 victory.</p>
<img src="/news/presi_3.jpeg" alt="">
<p>The first half saw the National Team score three tries, converting two for a 16-0 lead. Despite a spirited effort by the President’s Team, who managed a try and conversion in the second half, the National Team added two more tries and a conversion to seal the win.</p>
<hr>
<h1>Women’s National Team Outclasses Opponents</h1>
<p>In the women’s division, the National Team continued their dominance, securing a 22-12 win against the President’s Team. The first half ended 10-0, with the National Team scoring two tries and converting one.</p>
<img src="/news/presi_4.jpeg" alt="">
<p>The second half offered more excitement as both teams scored three tries each. However, neither side could convert their kicks, resulting in a 12-12 draw for the half. The National Team’s strong first-half performance proved decisive, securing the overall victory. </p>
<hr>
<h1>Men’s National Team Stunned in Narrow Loss</h1>
<p>The day’s highlight was the men’s clash, where the National Team faced a resurgent President’s Team. In a dramatic turn of events, the President’s Team claimed a 20-18 victory, marking the National Team’s first defeat in three years. </p>
<img src="/news/presi_5.jpeg" alt="">
<p>The first half ended 14-10 in favor of the President’s Team, who scored three tries and converted one. The National Team responded with two tries and a conversion, narrowing the gap.</p>
<p>In the second half, the National Team surged ahead with two tries, taking an 18-14 lead. However, with just three minutes left, Jonathan Adotey scored a try for the President’s Team, and Darryl Amoatey’s precision conversion secured a thrilling 20-18 win. </p>
<hr>
<h1>A Celebration of Growth and Innovation</h1>
<p>The President’s Cup 2024 was graced by Keith McMahon, Deputy UK High Commissioner, who commended the RLFG’s efforts in nurturing talent and promoting inclusivity in the sport. Beyond the matches, fans and players had the opportunity to engage with the esports version of rugby league, showcasing the Federation’s innovative approach to expanding the sport’s appeal.</p>
<p>As the final whistle blew on an unforgettable day, the 2024 President’s Cup not only celebrated the sport’s past but also underscored its promising future in Ghana. With leaders like Mrs. Juliana Storey at the helm, rugby league is poised to continue its remarkable journey in the years to come.</p>', '/news/presi_2.jpeg', 'competitions', array['Competitions', 'President’s Cup']::text[], 'published', '2024-11-26'::timestamptz, '[{"type": "paragraph", "content": "This year’s event was particularly significant as it celebrated Mrs. Juliana Storey, the first female president of the Rugby League Federation Ghana (RLFG). Under her leadership, the sport continues to gain momentum, and her vision for elevating rugby league to new heights was celebrated throughout the day."}, {"type": "paragraph", "content": "In its fourth year, the President’s Cup, which debuted in 2021, has evolved into a multi-division competition featuring men’s, women’s, and boys’ teams. Over 100 players from various communities, senior and junior high schools participated in this year’s event, further highlighting the sport’s grassroots development."}, {"type": "spacer"}, {"type": "heading", "content": "U19 Boys: National Team Dominates the Day", "attrs": {"level": "one", "decoration": "bold"}}, {"type": "paragraph", "content": "The day opened with a clash between the U19 Boys’ National Team and the President’s Team, comprising young talents from Awutu Winton SHS, Pentecost SHS, Aduman SHS, St. Michael SHS, and Akrofrom JHS. The National Team showcased their strength with a commanding 26-6 victory."}, {"type": "image", "src": "/news/presi_3.jpeg", "size": "contain"}, {"type": "paragraph", "content": "The first half saw the National Team score three tries, converting two for a 16-0 lead. Despite a spirited effort by the President’s Team, who managed a try and conversion in the second half, the National Team added two more tries and a conversion to seal the win."}, {"type": "spacer"}, {"type": "heading", "content": "Women’s National Team Outclasses Opponents", "attrs": {"level": "one", "decoration": "bold"}}, {"type": "paragraph", "content": "In the women’s division, the National Team continued their dominance, securing a 22-12 win against the President’s Team. The first half ended 10-0, with the National Team scoring two tries and converting one."}, {"type": "image", "src": "/news/presi_4.jpeg", "size": "contain"}, {"type": "paragraph", "content": "The second half offered more excitement as both teams scored three tries each. However, neither side could convert their kicks, resulting in a 12-12 draw for the half. The National Team’s strong first-half performance proved decisive, securing the overall victory. "}, {"type": "spacer"}, {"type": "heading", "content": "Men’s National Team Stunned in Narrow Loss", "attrs": {"level": "one", "decoration": "bold"}}, {"type": "paragraph", "content": "The day’s highlight was the men’s clash, where the National Team faced a resurgent President’s Team. In a dramatic turn of events, the President’s Team claimed a 20-18 victory, marking the National Team’s first defeat in three years. "}, {"type": "image", "src": "/news/presi_5.jpeg", "size": "contain"}, {"type": "paragraph", "content": "The first half ended 14-10 in favor of the President’s Team, who scored three tries and converted one. The National Team responded with two tries and a conversion, narrowing the gap."}, {"type": "paragraph", "content": "In the second half, the National Team surged ahead with two tries, taking an 18-14 lead. However, with just three minutes left, Jonathan Adotey scored a try for the President’s Team, and Darryl Amoatey’s precision conversion secured a thrilling 20-18 win. "}, {"type": "spacer"}, {"type": "heading", "content": "A Celebration of Growth and Innovation", "attrs": {"level": "one", "decoration": "bold"}}, {"type": "paragraph", "content": "The President’s Cup 2024 was graced by Keith McMahon, Deputy UK High Commissioner, who commended the RLFG’s efforts in nurturing talent and promoting inclusivity in the sport. Beyond the matches, fans and players had the opportunity to engage with the esports version of rugby league, showcasing the Federation’s innovative approach to expanding the sport’s appeal."}, {"type": "paragraph", "content": "As the final whistle blew on an unforgettable day, the 2024 President’s Cup not only celebrated the sport’s past but also underscored its promising future in Ghana. With leaders like Mrs. Juliana Storey at the helm, rugby league is poised to continue its remarkable journey in the years to come."}]'::jsonb),
  ('rlfg-hosts-presidents-cup-with-uk-deputy-high-commissioner', 'RLFG Hosts President’s Cup with UK Deputy High Commissioner as Guest', 'The Rugby League Federation Ghana (RLFG) is thrilled to announce the 2024 President’s Cup, scheduled for Sunday, November 24, 2024, at the Legon Rugby Stadium, Accra. This year’s event marks a milestone with the introduction of Youth and Women’s matches, highlighting RLFG’s dedication to fostering inclusivity and expanding the sport’s reach across Ghana.', '<p>The President’s Cup will bring together Ghana’s finest rugby league players in a thrilling matchup between the National Rugby League Team and the President’s XIII (National Team B). &#x27;RLFG Hosts President’s Cup with UK Deputy High Commissioner as Guest&#x27;</p>
<p>National Team (Men): Joseph Andoh, Abraham Adjetey, Nathaniel Sekyi, Emmanuel Bonney, John Haywood, Abugre Osman, Kofi Adusei, Jeff Agboku, Freeman Azu, Samuel Kanu, Gizo Fillmore, Gabriel Dua-Quaye, Gerrard Aidoo, Benjamin Fiawoo, Albert Ghartey, Michael Abbeyquaye.</p>
<p>President’s Team (Men): Manu Godfred, Asaah Joseph, Wahid Issah, Ofori A. Williams, Ansere Francis, Frimpong Sampson, Toffic Ahmed, Morrison Enock, Obeng Bright, Oheneba Richard, Agyapong Sumel, Mensah Anthony Prince, Ali Sadat, Asare Emmanuel, Aboagye Felix, Appiah Isaac, Owusu Francis, Bashiru Ibrahim, Inusah Hamza, Jamal Yussif, Livingstone Adjetey, Bryan Torgbor, Francis Bonapart.</p>
<p>National Team (Women): Hilaria Wuaku, Henrietta Arhin, Rosemary Sewornu, Ivy Benyah, Rita Afelibiik, Bernice Belele, Jennifer Moncar, Ecida Antwi, Jacqueline Ansah, Millicent Njomaba, Celestine Kumah, Rejoice Osei, Fati Bhom, Zainab Umar, Precious Andoh, Fauzia Musah Larry.</p>
<p>President’s Team (Women): Elizabeth Adongo, Firmina Akusung, Estelle Haizel, Dorcas Gakpo, Sheila Tettey, Margaret Tuffour, Celestine Segbedzie, Charity Asupah, Emmanuella Esseku, Leticia Zormelo, Naa Shormey Nortey, Brafi Princess, Amoanimaa Jessica, Bayala Musharafa, Nketia Yeboah, Amissah Esther, Boakye Kyei Rose, Boateng Esther, Sina Hafsah, Mauna Issah, Asare Patience, Ezuka Ezra, Antwi Comfort, Okyere Dorothy, Aseye Akuklu.</p>
<p>National Team (Youth): Oliver Puman, Jordan Annan, Emmanuel Amoah-Acheampong, Tony Tawiah, Bright Bawah, Riddick Alibah, Elvis Ayertey, David Nartey, William Pearce Biney, Yakubu Suleman, Julius Fiakpornu, Bilal Abdallah, John Bless Mensah, Adams Marsuu, Chris Da Gama, Philip Asomani.</p>
<p>President’s Team (Youth): Tony Agbemenu, Jonathan Adotey, Sadik Ahmed, Michael Egyir, Abass Farouk, Jonas Moorkaar, Kevin Boadu, Stephen Tetteh, Sherif Arimiyaw, Stanley Dzagah, Akwei Godfred, Elikem Kuwornu, Collins Ofosu, Godfred Aikins, Michael Quaye, Richard Browne Asare, Godwin Asamoah.</p>
<p><strong>Event Schedule</strong></p>
<ul><li>Youth Match: 12:00 PM</li><li>Women’s Match: 1:30 PM</li><li>Men’s Match: 3:30 PM</li></ul>
<p>[{&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/pres1.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/pres2.jpeg&#x27;}]</p>
<p>For the first time, youth and women’s teams from the Ashanti Region will participate, showcasing the growth of rugby league in regions beyond the capital.</p>
<p>The RLFG is honored to host the British Deputy High Commissioner, Mr. Keith McMahon, as the Special Guest of Honor. His presence underscores the international recognition of rugby league’s development in Ghana and highlights the power of sports diplomacy in strengthening ties between Ghana and the United Kingdom.</p>
<blockquote><p>The 2024 President&#x27;s Cup celebrates the exceptional talent and unity in Ghana’s rugby league community. With the addition of women’s and youth teams, we continue to drive inclusivity, diversity, and pride across our nation.</p><p><em>Mrs. Juliana Storey —  President - RLFG</em></p></blockquote>
<blockquote><p>We are excited to host the 2024 President&#x27;s Cup, uniting Ghana’s rugby league talent while promoting peace and unity. The addition of women’s and youth teams highlights the growth and inclusivity of our sport.</p><p><em>Jafaru Awudu Mustapha — General Manager - RLFG</em></p></blockquote>
<p>The RLFG extends an open invitation to sports enthusiasts, peace advocates, and all Ghanaians to join in this landmark event. Together, we can celebrate the power of rugby league to unite communities, promote peace, and showcase Ghana’s sporting excellence.</p>', '/news/pres_cover.jpeg', 'competitions', array['Competitions', 'President’s Cup']::text[], 'published', '2024-11-18'::timestamptz, '[{"type": "paragraph", "content": "The President’s Cup will bring together Ghana’s finest rugby league players in a thrilling matchup between the National Rugby League Team and the President’s XIII (National Team B). ''RLFG Hosts President’s Cup with UK Deputy High Commissioner as Guest''"}, {"type": "paragraph", "content": "National Team (Men): Joseph Andoh, Abraham Adjetey, Nathaniel Sekyi, Emmanuel Bonney, John Haywood, Abugre Osman, Kofi Adusei, Jeff Agboku, Freeman Azu, Samuel Kanu, Gizo Fillmore, Gabriel Dua-Quaye, Gerrard Aidoo, Benjamin Fiawoo, Albert Ghartey, Michael Abbeyquaye."}, {"type": "paragraph", "content": "President’s Team (Men): Manu Godfred, Asaah Joseph, Wahid Issah, Ofori A. Williams, Ansere Francis, Frimpong Sampson, Toffic Ahmed, Morrison Enock, Obeng Bright, Oheneba Richard, Agyapong Sumel, Mensah Anthony Prince, Ali Sadat, Asare Emmanuel, Aboagye Felix, Appiah Isaac, Owusu Francis, Bashiru Ibrahim, Inusah Hamza, Jamal Yussif, Livingstone Adjetey, Bryan Torgbor, Francis Bonapart."}, {"type": "paragraph", "content": "National Team (Women): Hilaria Wuaku, Henrietta Arhin, Rosemary Sewornu, Ivy Benyah, Rita Afelibiik, Bernice Belele, Jennifer Moncar, Ecida Antwi, Jacqueline Ansah, Millicent Njomaba, Celestine Kumah, Rejoice Osei, Fati Bhom, Zainab Umar, Precious Andoh, Fauzia Musah Larry."}, {"type": "paragraph", "content": "President’s Team (Women): Elizabeth Adongo, Firmina Akusung, Estelle Haizel, Dorcas Gakpo, Sheila Tettey, Margaret Tuffour, Celestine Segbedzie, Charity Asupah, Emmanuella Esseku, Leticia Zormelo, Naa Shormey Nortey, Brafi Princess, Amoanimaa Jessica, Bayala Musharafa, Nketia Yeboah, Amissah Esther, Boakye Kyei Rose, Boateng Esther, Sina Hafsah, Mauna Issah, Asare Patience, Ezuka Ezra, Antwi Comfort, Okyere Dorothy, Aseye Akuklu."}, {"type": "paragraph", "content": "National Team (Youth): Oliver Puman, Jordan Annan, Emmanuel Amoah-Acheampong, Tony Tawiah, Bright Bawah, Riddick Alibah, Elvis Ayertey, David Nartey, William Pearce Biney, Yakubu Suleman, Julius Fiakpornu, Bilal Abdallah, John Bless Mensah, Adams Marsuu, Chris Da Gama, Philip Asomani."}, {"type": "paragraph", "content": "President’s Team (Youth): Tony Agbemenu, Jonathan Adotey, Sadik Ahmed, Michael Egyir, Abass Farouk, Jonas Moorkaar, Kevin Boadu, Stephen Tetteh, Sherif Arimiyaw, Stanley Dzagah, Akwei Godfred, Elikem Kuwornu, Collins Ofosu, Godfred Aikins, Michael Quaye, Richard Browne Asare, Godwin Asamoah."}, {"type": "list", "name": "Event Schedule", "content": ["Youth Match: 12:00 PM", "Women’s Match: 1:30 PM", "Men’s Match: 3:30 PM"], "attrs": {"bullets": true}}, {"type": "gallery", "content": [{"type": "image", "src": "/news/pres1.jpeg"}, {"type": "image", "src": "/news/pres2.jpeg"}]}, {"type": "paragraph", "content": "For the first time, youth and women’s teams from the Ashanti Region will participate, showcasing the growth of rugby league in regions beyond the capital."}, {"type": "paragraph", "content": "The RLFG is honored to host the British Deputy High Commissioner, Mr. Keith McMahon, as the Special Guest of Honor. His presence underscores the international recognition of rugby league’s development in Ghana and highlights the power of sports diplomacy in strengthening ties between Ghana and the United Kingdom."}, {"type": "quote", "preface": "", "content": "The 2024 President''s Cup celebrates the exceptional talent and unity in Ghana’s rugby league community. With the addition of women’s and youth teams, we continue to drive inclusivity, diversity, and pride across our nation.", "by": "Mrs. Juliana Storey", "image": "/team/12.png", "designation": " President - RLFG"}, {"type": "quote", "preface": "", "content": "We are excited to host the 2024 President''s Cup, uniting Ghana’s rugby league talent while promoting peace and unity. The addition of women’s and youth teams highlights the growth and inclusivity of our sport.", "by": "Jafaru Awudu Mustapha", "image": "/team/2.png", "designation": "General Manager - RLFG"}, {"type": "paragraph", "content": "The RLFG extends an open invitation to sports enthusiasts, peace advocates, and all Ghanaians to join in this landmark event. Together, we can celebrate the power of rugby league to unite communities, promote peace, and showcase Ghana’s sporting excellence."}]'::jsonb),
  ('tigers-panthers-dominate-2024-9s-championship', 'Tigers and Panthers Triumph in Men, Women, and Youth at 2024 9s Tournament', 'Accra, Ghana — October in Accra was electrifying as Rugby League Federation Ghana (RLFG) wrapped up the celebrated 2024 Ghana Rugby League 9s tournament. Hosted every Sunday in October at the University of Ghana Rugby Field, this year’s tournament brought thrilling action, emerging talents, and a unique focus on community health that united fans and players alike. Across men’s, women’s, and youth divisions, RLFG put on a month-long showcase, capturing the true spirit of rugby league in Ghana.', '<p>Beyond being a thrilling sports event, the tournament spotlighted wellness initiatives, offering free breast screenings to spectators and rugby league participants. Through a partnership with Life Healthcare, RLFG transformed this year’s tournament into a holistic experience that blended competitive sports with health awareness.</p>
<h1>Men’s Division: Nungua Tigers Rise to Victory</h1>
<p>In a high-stakes showdown, Nungua Tigers seized the men’s title, triumphing through a challenging two-round robin format. In the final against defending champions, Skolars, Tigers clinched a close 13-10 victory, breaking Skolars&#x27; winning streak. Throughout the tournament, Tigers demonstrated resilience and tactical precision, led by standout performances from Gideon Klugey, who scored an impressive 11 tries, and Kofi Montchon, who dominated with 20 conversions. This victory firmly establishes Nungua Tigers as a new powerhouse in Ghana’s men’s rugby league 9s.</p>
<p>[{&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/9snews1.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/9snews3.jpeg&#x27;}]</p>
<h1>Women’s Division: Accra Panthers Defend Their Title</h1>
<p>The women’s division saw Accra Panthers extend their legacy, successfully defending their championship title. Competing in a round-robin series against Accra Majestics, Bulls, and Nungua Tigers, Panthers faced off with Nungua Tigers in a hard-fought final, emerging victorious with a 12-0 score. Star players Margaret Tuffour (Accra Panthers) and Ivy Benyah (Nungua Tigers) tied with five tries each, with Benyah also leading in conversions by the end of the tournament. Accra Panthers’ resilience and skill once again established them as the team to beat in women’s rugby league 9s in Ghana.</p>
<p>[{&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/9snews4.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/9snews9.jpeg&#x27;}]</p>
<h1>Youth Division: Panthers Showcase the Future of Rugby League</h1>
<p>In the youth division, the tournament showcased emerging talent and promising young players. Accra Panthers’ youth team, in their first rugby league 9s appearance, dominated the field with a 12-0 win over Accra Majestics in the final. This inaugural victory adds to Accra Panthers’ legacy and reflects RLFG’s commitment to youth development. Standout youth players Kofi Adusei and Jamal Yussif scored three tries each during the tournament, highlighting the bright future of rugby league in Ghana.</p>
<p>[{&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/9snews7.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/9snews6.jpeg&#x27;}]</p>
<h1>A Unique Blend of Sports and Health</h1>
<p>RLFG’s collaboration with Life Healthcare made this year’s tournament not only a competitive event but also a community-focused health initiative. Free breast screenings were provided, making health services accessible to fans and players alike. This emphasis on community wellness reinforced RLFG’s commitment to using rugby league as a force for positive impact.</p>
<blockquote><p>This tournament represents the strength of our players and the power of our community. We’re thrilled to blend rugby league with health initiatives, bringing our fans and players together for a purpose greater than sport.</p><p><em>Riddick Alibah —  Regional Manager - RLFG</em></p></blockquote>
<p>With 45 matches played and thousands of fans in attendance, the 2024 Ghana Rugby League 9s tournament leaves an enduring legacy. RLFG looks to the future with a focus on expanding rugby league and promoting community health across Ghana.</p>
<p>The event was proudly supported by Polytank, MX24Sports, Ghanaian Times, Jibu, Firm Foods, First Love Therapeutic Massage, Pass Therapy and Wellness Center, Philans Rehab Services, Salford Red Devils, Regardless, Radical, Life Healthcare Center, and Bariki Enterprise.</p>', '/news/9snews8.jpeg', 'competitions', array['Competitions', '9s Championship']::text[], 'published', '2024-10-29'::timestamptz, '[{"type": "paragraph", "content": "Beyond being a thrilling sports event, the tournament spotlighted wellness initiatives, offering free breast screenings to spectators and rugby league participants. Through a partnership with Life Healthcare, RLFG transformed this year’s tournament into a holistic experience that blended competitive sports with health awareness."}, {"type": "heading", "content": "Men’s Division: Nungua Tigers Rise to Victory", "attrs": {"level": "one", "decoration": "bold"}}, {"type": "paragraph", "content": "In a high-stakes showdown, Nungua Tigers seized the men’s title, triumphing through a challenging two-round robin format. In the final against defending champions, Skolars, Tigers clinched a close 13-10 victory, breaking Skolars'' winning streak. Throughout the tournament, Tigers demonstrated resilience and tactical precision, led by standout performances from Gideon Klugey, who scored an impressive 11 tries, and Kofi Montchon, who dominated with 20 conversions. This victory firmly establishes Nungua Tigers as a new powerhouse in Ghana’s men’s rugby league 9s."}, {"type": "gallery", "content": [{"type": "image", "src": "/news/9snews1.jpeg"}, {"type": "image", "src": "/news/9snews3.jpeg"}]}, {"type": "heading", "content": "Women’s Division: Accra Panthers Defend Their Title", "attrs": {"level": "one", "decoration": "bold"}}, {"type": "paragraph", "content": "The women’s division saw Accra Panthers extend their legacy, successfully defending their championship title. Competing in a round-robin series against Accra Majestics, Bulls, and Nungua Tigers, Panthers faced off with Nungua Tigers in a hard-fought final, emerging victorious with a 12-0 score. Star players Margaret Tuffour (Accra Panthers) and Ivy Benyah (Nungua Tigers) tied with five tries each, with Benyah also leading in conversions by the end of the tournament. Accra Panthers’ resilience and skill once again established them as the team to beat in women’s rugby league 9s in Ghana."}, {"type": "gallery", "content": [{"type": "image", "src": "/news/9snews4.jpeg"}, {"type": "image", "src": "/news/9snews9.jpeg"}]}, {"type": "heading", "content": "Youth Division: Panthers Showcase the Future of Rugby League", "attrs": {"level": "one", "decoration": "bold"}}, {"type": "paragraph", "content": "In the youth division, the tournament showcased emerging talent and promising young players. Accra Panthers’ youth team, in their first rugby league 9s appearance, dominated the field with a 12-0 win over Accra Majestics in the final. This inaugural victory adds to Accra Panthers’ legacy and reflects RLFG’s commitment to youth development. Standout youth players Kofi Adusei and Jamal Yussif scored three tries each during the tournament, highlighting the bright future of rugby league in Ghana."}, {"type": "gallery", "content": [{"type": "image", "src": "/news/9snews7.jpeg"}, {"type": "image", "src": "/news/9snews6.jpeg"}]}, {"type": "heading", "content": "A Unique Blend of Sports and Health", "attrs": {"level": "one", "decoration": "bold"}}, {"type": "paragraph", "content": "RLFG’s collaboration with Life Healthcare made this year’s tournament not only a competitive event but also a community-focused health initiative. Free breast screenings were provided, making health services accessible to fans and players alike. This emphasis on community wellness reinforced RLFG’s commitment to using rugby league as a force for positive impact."}, {"type": "quote", "preface": "", "content": "This tournament represents the strength of our players and the power of our community. We’re thrilled to blend rugby league with health initiatives, bringing our fans and players together for a purpose greater than sport.", "by": "Riddick Alibah", "image": null, "designation": " Regional Manager - RLFG"}, {"type": "paragraph", "content": "With 45 matches played and thousands of fans in attendance, the 2024 Ghana Rugby League 9s tournament leaves an enduring legacy. RLFG looks to the future with a focus on expanding rugby league and promoting community health across Ghana."}, {"type": "paragraph", "content": "The event was proudly supported by Polytank, MX24Sports, Ghanaian Times, Jibu, Firm Foods, First Love Therapeutic Massage, Pass Therapy and Wellness Center, Philans Rehab Services, Salford Red Devils, Regardless, Radical, Life Healthcare Center, and Bariki Enterprise."}]'::jsonb),
  ('rugby-league-and-esports-form-groundbreaking-partnership', 'RLFG and Esports Association, Ghana Form Groundbreaking Partnership', 'The Rugby League Federation Ghana (RLFG) has announced an exciting partnership with Esports Association, Ghana, marking a significant milestone in the evolution of sports in the country. This innovative collaboration aims to merge the physical intensity of rugby league with the dynamic world of esports, offering a unique experience for fans and players alike.', '<p>Set against the backdrop of the ongoing Ghana Rugby League 9s Championship, the partnership will culminate in the inaugural Esports Rugby League competition on October 27, 2024. This groundbreaking event will allow fans to engage with rugby league in a fresh, digital way, combining live matches with thrilling esports tournaments.</p>
<blockquote><p>Jafaru Awudu Mustapha, General Manager of RLFG, expressed his excitement:</p><p>This partnership marks a new era for rugby league in Ghana. By working with Esports Association, Ghana, we are expanding our reach and redefining how fans interact with the sport. Our goal is to connect with a broader audience, particularly the youth, who are passionate about gaming.</p><p><em>Jafaru Awudu Mustapha —  General Manager - RLFG</em></p></blockquote>
<p>The partnership aims to enhance fan experiences and foster youth development. RLFG and Esports Association, Ghana will jointly host youth training camps, combining physical rugby coaching with esports skill development. This initiative will inspire young athletes and gamers, giving them opportunities to excel in both fields.</p>
<blockquote><p>Ebenezer Kwesi Hayford, President of Esports Association, Ghana, highlighted the importance of this collaboration:</p><p>We are thrilled to collaborate with RLFG. This initiative will introduce esports to traditional sports fans while showcasing the potential of gaming. Together, we aim to create an unparalleled sports experience that excites and engages the Ghanaian community</p><p><em>Ebenezer Kwesi Hayford —  President  - Esports Association, Ghana</em></p></blockquote>
<p>A key feature of this partnership is its focus on fan engagement. By integrating esports into traditional rugby events, RLFG and Esports Association, Ghana aim to attract a diverse audience, including tech enthusiasts and gamers who may not have previously followed rugby league. Fans can look forward to experiencing live rugby matches alongside competitive esports tournaments, creating a vibrant atmosphere that bridges the gap between the two worlds.</p>
<p>[{&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/ni_0003.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/ni__001.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/ni__002.jpeg&#x27;}, {&#x27;type&#x27;: &#x27;image&#x27;, &#x27;src&#x27;: &#x27;/news/ni_0004.jpeg&#x27;}]</p>
<p>Beyond improving fan experiences, the partnership will support social impact initiatives in local communities. Leveraging the popularity of both sports, RLFG and Esports Association, Ghana will promote grassroots development and community outreach.</p>
<blockquote><p>Marshall Nortey, Technical Director of RLFG, emphasized the educational aspect:</p><p>Integrating esports with rugby league is not just about entertainment; it’s about learning. Through our youth programs, we aim to provide players and stakeholders with a deeper understanding of the game, from its rules to its tactical elements</p><p><em>Marshall Nortey — Technical Director - RLFG</em></p></blockquote>
<p>As the Rugby League 9s Championship continues, anticipation builds for the upcoming Esports Rugby League tournament. This innovative partnership represents a pivotal step forward in Ghana&#x27;s sports landscape, setting the stage for future collaborations between traditional sports and digital platforms.</p>
<p>Stay tuned for more updates as RLFG and Esports Association, Ghana prepare to deliver an unforgettable experience for fans, players, and the wider community.</p>
<p>About Rugby League Federation Ghana (RLFG): The RLFG is the official governing body for rugby league in Ghana, dedicated to the sport&#x27;s development through grassroots programs and national competitions.</p>
<p>About Esports Association, Ghana: Esports Association, Ghana is committed to advancing competitive gaming in the country, providing platforms for gamers and promoting esports as an essential component of the future of sports.</p>', '/news/rlfgxesports.jpeg', 'Partnerships', array['Partnerships', 'Sponsorships', 'Corporate', 'Growth']::text[], 'published', '2024-10-09'::timestamptz, '[{"type": "paragraph", "content": "Set against the backdrop of the ongoing Ghana Rugby League 9s Championship, the partnership will culminate in the inaugural Esports Rugby League competition on October 27, 2024. This groundbreaking event will allow fans to engage with rugby league in a fresh, digital way, combining live matches with thrilling esports tournaments."}, {"type": "quote", "preface": "Jafaru Awudu Mustapha, General Manager of RLFG, expressed his excitement:", "content": "This partnership marks a new era for rugby league in Ghana. By working with Esports Association, Ghana, we are expanding our reach and redefining how fans interact with the sport. Our goal is to connect with a broader audience, particularly the youth, who are passionate about gaming.", "by": "Jafaru Awudu Mustapha", "image": "/team/2.png", "designation": " General Manager - RLFG"}, {"type": "paragraph", "content": "The partnership aims to enhance fan experiences and foster youth development. RLFG and Esports Association, Ghana will jointly host youth training camps, combining physical rugby coaching with esports skill development. This initiative will inspire young athletes and gamers, giving them opportunities to excel in both fields."}, {"type": "quote", "preface": "Ebenezer Kwesi Hayford, President of Esports Association, Ghana, highlighted the importance of this collaboration:", "content": "We are thrilled to collaborate with RLFG. This initiative will introduce esports to traditional sports fans while showcasing the potential of gaming. Together, we aim to create an unparalleled sports experience that excites and engages the Ghanaian community", "by": "Ebenezer Kwesi Hayford", "image": "/people/espres.png", "designation": " President  - Esports Association, Ghana"}, {"type": "paragraph", "content": "A key feature of this partnership is its focus on fan engagement. By integrating esports into traditional rugby events, RLFG and Esports Association, Ghana aim to attract a diverse audience, including tech enthusiasts and gamers who may not have previously followed rugby league. Fans can look forward to experiencing live rugby matches alongside competitive esports tournaments, creating a vibrant atmosphere that bridges the gap between the two worlds."}, {"type": "gallery", "content": [{"type": "image", "src": "/news/ni_0003.jpeg"}, {"type": "image", "src": "/news/ni__001.jpeg"}, {"type": "image", "src": "/news/ni__002.jpeg"}, {"type": "image", "src": "/news/ni_0004.jpeg"}]}, {"type": "paragraph", "content": "Beyond improving fan experiences, the partnership will support social impact initiatives in local communities. Leveraging the popularity of both sports, RLFG and Esports Association, Ghana will promote grassroots development and community outreach."}, {"type": "quote", "preface": "Marshall Nortey, Technical Director of RLFG, emphasized the educational aspect:", "content": "Integrating esports with rugby league is not just about entertainment; it’s about learning. Through our youth programs, we aim to provide players and stakeholders with a deeper understanding of the game, from its rules to its tactical elements", "by": "Marshall Nortey", "image": "/team/6.png", "designation": "Technical Director - RLFG"}, {"type": "paragraph", "content": "As the Rugby League 9s Championship continues, anticipation builds for the upcoming Esports Rugby League tournament. This innovative partnership represents a pivotal step forward in Ghana''s sports landscape, setting the stage for future collaborations between traditional sports and digital platforms."}, {"type": "paragraph", "content": "Stay tuned for more updates as RLFG and Esports Association, Ghana prepare to deliver an unforgettable experience for fans, players, and the wider community."}, {"type": "paragraph", "content": "About Rugby League Federation Ghana (RLFG): The RLFG is the official governing body for rugby league in Ghana, dedicated to the sport''s development through grassroots programs and national competitions."}, {"type": "paragraph", "content": "About Esports Association, Ghana: Esports Association, Ghana is committed to advancing competitive gaming in the country, providing platforms for gamers and promoting esports as an essential component of the future of sports."}]'::jsonb),
  ('rugby-league-launches-9s-competition-slated-for-october', 'RLFG Presents Ghana Rugby League 9s This October', 'The Rugby League Federation Ghana (RLFG) will host the Ghana Rugby League 9s tournament from October 6 to October 27, 2024, with matches taking place every Sunday in October at 10:30 am at the University of Ghana Rugby Field.', '<p>The event features six teams—Accra Panthers, Accra Majestics, UG Titans, Skolars, Bulls, and Nungua Tigers—competing in men’s, women’s, and youth divisions. Skolars and Accra Panthers will be defending their titles in the men’s and women’s categories, respectively, while African Warriors are the defending champions in the youth division.</p>
<img src="/news/9steams.png" alt="">
<p>Alongside the 45 matches, RLFG is emphasizing community health by offering breast and prostate screenings every Sunday. In collaboration with Esports Association Ghana, the tournament will also feature an Esports Rugby League event on October 27.</p>
<blockquote><p>RLFG President. Mrs Juliana Storey said</p><p>We’re not just delivering rugby league, we’re serving up an event that integrates the sport with health, technology, and inclusivity. It’s a chance for fans to enjoy the game while participating in activities that benefit the whole community</p><p><em>Mrs Juliana Storey — President - Rugby League Federation Ghana</em></p></blockquote>
<p>The Ghana Rugby League 9s wouldn’t be possible without the support of generous partners like</p>
<p>[{&#x27;name&#x27;: &#x27;Polytank&#x27;, &#x27;logo&#x27;: &#x27;/partners/polytank.png&#x27;}, {&#x27;name&#x27;: &#x27;MX24Sports&#x27;, &#x27;logo&#x27;: &#x27;/partners/mx24sports.png&#x27;}, {&#x27;name&#x27;: &#x27;Ghanaian Times&#x27;, &#x27;logo&#x27;: &#x27;/partners/ghtimes.png&#x27;}, {&#x27;name&#x27;: &#x27;Jibu&#x27;, &#x27;logo&#x27;: &#x27;/partners/jibu.png&#x27;}, {&#x27;name&#x27;: &#x27;Firm Foods&#x27;, &#x27;logo&#x27;: &#x27;/partners/firmfoods.png&#x27;}, {&#x27;name&#x27;: &#x27;First Love Therapeutic Massage&#x27;, &#x27;logo&#x27;: &#x27;/partners/firstlovetm.png&#x27;}, {&#x27;name&#x27;: &#x27;Pass Therapy and Wellness Center&#x27;, &#x27;logo&#x27;: &#x27;/partners/passtmc.png&#x27;}, {&#x27;name&#x27;: &#x27;Salford Red Devils&#x27;, &#x27;logo&#x27;: &#x27;/partners/salford.png&#x27;}, {&#x27;name&#x27;: &#x27;Regardless&#x27;, &#x27;logo&#x27;: &#x27;/partners/polytank.png&#x27;}, {&#x27;name&#x27;: &#x27;Radical&#x27;, &#x27;logo&#x27;: &#x27;/partners/radical.png&#x27;}, {&#x27;name&#x27;: &#x27;Life Healthcare Center&#x27;, &#x27;logo&#x27;: &#x27;/partners/lhc.png&#x27;}, {&#x27;name&#x27;: &#x27;Aladdin Print House &amp; Technologies&#x27;, &#x27;logo&#x27;: &#x27;/partners/aladin.png&#x27;}, {&#x27;name&#x27;: &#x27;Philanx Rehab Services&#x27;, &#x27;logo&#x27;: &#x27;/partners/philanx.png&#x27;}, {&#x27;name&#x27;: &#x27;ESports Ghana Association &#x27;, &#x27;logo&#x27;: &#x27;/partners/esports.png&#x27;}, {&#x27;name&#x27;: &#x27;Velocity Sports Labs&#x27;, &#x27;logo&#x27;: &#x27;/partners/vsl.png&#x27;}]</p>
<p>What is Rugby League 9s? Rugby League 9s is a fast-paced version of rugby league, featuring nine players per team instead of the traditional thirteen. The game emphasizes speed, agility, and open-field play, making it an exciting and dynamic version of the sport. Fans can expect fast action and thrilling tries throughout the tournament.</p>
<p>Fans are encouraged to join this unique experience of rugby, health, and community engagement.</p>
<p><a href="/fixtures">View Fixtures</a></p>', '/news/9scover.png', 'Competition News', array['9s Championship', 'Rugby 9s', 'Competitions']::text[], 'published', '2024-10-01'::timestamptz, '[{"type": "paragraph", "content": "The event features six teams—Accra Panthers, Accra Majestics, UG Titans, Skolars, Bulls, and Nungua Tigers—competing in men’s, women’s, and youth divisions. Skolars and Accra Panthers will be defending their titles in the men’s and women’s categories, respectively, while African Warriors are the defending champions in the youth division."}, {"type": "image", "src": "/news/9steams.png", "size": "contain"}, {"type": "paragraph", "content": "Alongside the 45 matches, RLFG is emphasizing community health by offering breast and prostate screenings every Sunday. In collaboration with Esports Association Ghana, the tournament will also feature an Esports Rugby League event on October 27."}, {"type": "quote", "preface": "RLFG President. Mrs Juliana Storey said", "content": "We’re not just delivering rugby league, we’re serving up an event that integrates the sport with health, technology, and inclusivity. It’s a chance for fans to enjoy the game while participating in activities that benefit the whole community", "by": "Mrs Juliana Storey", "image": "/team/12.png", "designation": "President - Rugby League Federation Ghana"}, {"type": "partners", "preface": "The Ghana Rugby League 9s wouldn’t be possible without the support of generous partners like", "content": [{"name": "Polytank", "logo": "/partners/polytank.png"}, {"name": "MX24Sports", "logo": "/partners/mx24sports.png"}, {"name": "Ghanaian Times", "logo": "/partners/ghtimes.png"}, {"name": "Jibu", "logo": "/partners/jibu.png"}, {"name": "Firm Foods", "logo": "/partners/firmfoods.png"}, {"name": "First Love Therapeutic Massage", "logo": "/partners/firstlovetm.png"}, {"name": "Pass Therapy and Wellness Center", "logo": "/partners/passtmc.png"}, {"name": "Salford Red Devils", "logo": "/partners/salford.png"}, {"name": "Regardless", "logo": "/partners/polytank.png"}, {"name": "Radical", "logo": "/partners/radical.png"}, {"name": "Life Healthcare Center", "logo": "/partners/lhc.png"}, {"name": "Aladdin Print House & Technologies", "logo": "/partners/aladin.png"}, {"name": "Philanx Rehab Services", "logo": "/partners/philanx.png"}, {"name": "ESports Ghana Association ", "logo": "/partners/esports.png"}, {"name": "Velocity Sports Labs", "logo": "/partners/vsl.png"}]}, {"type": "paragraph", "content": "What is Rugby League 9s? Rugby League 9s is a fast-paced version of rugby league, featuring nine players per team instead of the traditional thirteen. The game emphasizes speed, agility, and open-field play, making it an exciting and dynamic version of the sport. Fans can expect fast action and thrilling tries throughout the tournament."}, {"type": "paragraph", "content": "Fans are encouraged to join this unique experience of rugby, health, and community engagement."}, {"type": "link", "content": "/fixtures", "attrs": {"display_as": "button", "text": "View Fixtures"}}]'::jsonb),
  ('beaufort-properties-wins-second-beach-rugby-league-title', ' Beaufort Properties Wins Second Beach Rugby League Title', 'The thrilling event featured 16 teams from diverse sectors battling for victory while also participating in a beach cleanup for World Beach Cleanup Day. From fierce rugby matches to community-led sustainability efforts, the Beach Rugby League proved it''s more than just a game—it''s a movement for positive change. Keep reading to discover key moments, standout teams, and how rugby is promoting environmental awareness in Ghana!', '<p>The second edition of the Beach Rugby League concluded in thrilling fashion at the Laboma Beach Resort on September 21, 2024, where Beaufort Properties defended their title, emerging as champions for the second consecutive time. The event brought together 16 teams from various sectors to battle it out in one of Ghana&#x27;s most exciting and fast-growing sports tournaments.</p>
<img src="/news/cleanup.jpeg" alt="">
<p>The day began with a communal beach cleanup exercise, in line with the Seventh World Beach Cleanup Day, as players, volunteers, and corporate Ghana united to clean up the beach before the games. Following the cleanup, attention quickly turned to the Beach Rugby League, which featured intense competition featuring 16 participating teams  grouped as follows:</p>
<p><strong>Participants</strong></p>
<ul><li>Group 1:  Bolt Ghana, Jibu Ghana, Ghana Wildlife Society, DHL</li><li>Group 2:  France Voluntaire Ghana, Ecozoil, Regardless Mode, CMA CGM </li><li>Group 3:  Rotary Club, Hapag Lloyd, Sahara Solace, Beaufort Properties</li><li>Group 4:  Street Sense Organisation, Lions Club, Polytank, Ghana Link</li></ul>
<img src="/news/cleanup_two.jpg" alt="">
<p>Each group delivered high-energy performances, with teams demonstrating skill, teamwork, and determination. After 31 hard-fought matches, Beaufort Properties emerged victorious, securing the top spot for the second consecutive year. Ghana Wildlife Society came in a close second, showcasing impressive resilience and skill throughout the tournament.</p>
<blockquote><p>Michael Agyei-Budu, CEO of Regardless Mode, one of the event’s key partners, praised the event’s success:</p><p>Beach Rugby League continues to grow, and this year was no different. The competition was fierce, and seeing how everyone came together for both the game and the beach cleanup has been truly inspiring</p><p><em>Michael Agyei-Budu — CEO - Regardless Mode</em></p></blockquote>
<blockquote><p>Kate Opoku, Country Leader for Let’s Do It Ghana, shared her thoughts on the event</p><p>The combination of beach rugby and cleanup efforts was incredible. It shows that we can take care of our planet while enjoying activities like rugby. This initiative goes beyond just sports—it&#x27;s about creating lasting impact.</p><p><em>Kate Opoku — Country Leader - Let’s Do It Ghana</em></p></blockquote>
<p>The event also combined the spirit of rugby with environmental consciousness. This initiative, part of World Beach Cleanup Day, highlighted the commitment of the Rugby League Federation Ghana to not only promote sports but also environmental sustainability.</p>
<img src="/news/cleanup_three.jpg" alt="">
<blockquote><p>Jafaru Awudu Mustapha, General Manager of Rugby League Federation Ghana, shared his thoughts:</p><p>This year’s tournament was a testament to the growing popularity of rugby league in Ghana. The addition of the beach cleanup makes this event even more special, showing how sport can have a positive impact beyond the field.</p><p><em>Jafaru Awudu Mustapha —  General Manager - Rugby League Federation Ghana</em></p></blockquote>', '/news/1.png', 'Impact Stories', array['Beach Rugby League', 'Championship', 'CSR', 'Community', 'Social Impact']::text[], 'published', '2024-09-26'::timestamptz, '[{"type": "paragraph", "content": "The second edition of the Beach Rugby League concluded in thrilling fashion at the Laboma Beach Resort on September 21, 2024, where Beaufort Properties defended their title, emerging as champions for the second consecutive time. The event brought together 16 teams from various sectors to battle it out in one of Ghana''s most exciting and fast-growing sports tournaments."}, {"type": "image", "src": "/news/cleanup.jpeg", "size": "banner"}, {"type": "paragraph", "content": "The day began with a communal beach cleanup exercise, in line with the Seventh World Beach Cleanup Day, as players, volunteers, and corporate Ghana united to clean up the beach before the games. Following the cleanup, attention quickly turned to the Beach Rugby League, which featured intense competition featuring 16 participating teams  grouped as follows:"}, {"type": "list", "name": "Participants", "content": ["Group 1:  Bolt Ghana, Jibu Ghana, Ghana Wildlife Society, DHL", "Group 2:  France Voluntaire Ghana, Ecozoil, Regardless Mode, CMA CGM ", "Group 3:  Rotary Club, Hapag Lloyd, Sahara Solace, Beaufort Properties", "Group 4:  Street Sense Organisation, Lions Club, Polytank, Ghana Link"], "attrs": {"bullets": true}}, {"type": "image", "src": "/news/cleanup_two.jpg", "size": "banner"}, {"type": "paragraph", "content": "Each group delivered high-energy performances, with teams demonstrating skill, teamwork, and determination. After 31 hard-fought matches, Beaufort Properties emerged victorious, securing the top spot for the second consecutive year. Ghana Wildlife Society came in a close second, showcasing impressive resilience and skill throughout the tournament."}, {"type": "quote", "preface": "Michael Agyei-Budu, CEO of Regardless Mode, one of the event’s key partners, praised the event’s success:", "content": "Beach Rugby League continues to grow, and this year was no different. The competition was fierce, and seeing how everyone came together for both the game and the beach cleanup has been truly inspiring", "by": "Michael Agyei-Budu", "image": null, "designation": "CEO - Regardless Mode"}, {"type": "quote", "preface": "Kate Opoku, Country Leader for Let’s Do It Ghana, shared her thoughts on the event", "content": "The combination of beach rugby and cleanup efforts was incredible. It shows that we can take care of our planet while enjoying activities like rugby. This initiative goes beyond just sports—it''s about creating lasting impact.", "by": "Kate Opoku", "image": null, "designation": "Country Leader - Let’s Do It Ghana"}, {"type": "paragraph", "content": "The event also combined the spirit of rugby with environmental consciousness. This initiative, part of World Beach Cleanup Day, highlighted the commitment of the Rugby League Federation Ghana to not only promote sports but also environmental sustainability."}, {"type": "image", "src": "/news/cleanup_three.jpg", "size": "banner"}, {"type": "quote", "preface": "Jafaru Awudu Mustapha, General Manager of Rugby League Federation Ghana, shared his thoughts:", "content": "This year’s tournament was a testament to the growing popularity of rugby league in Ghana. The addition of the beach cleanup makes this event even more special, showing how sport can have a positive impact beyond the field.", "by": "Jafaru Awudu Mustapha", "image": "/team/2.png", "designation": " General Manager - Rugby League Federation Ghana"}]'::jsonb),
  ('rlfg-announces-2024-national-rugby-league-teams', ' RLFG Announces 2024 National Rugby League Teams', 'After a rigorous selection process at the Origins Cup, these talented players will represent Ghana on the rugby league stage. A historic step forward for the sport in Ghana!', '<p>The Rugby League Federation Ghana (RLFG) is thrilled to announce the selection of its 2024 national teams for men, women, and youth. This year marks a historic moment as the Federation names its first-ever Youth National Team, further demonstrating its commitment to nurturing young talent and ensuring a bright future for rugby league in Ghana.</p>
<p>The selection process was rigorous and followed the recent 2024 Origins Cup, where players showcased their exceptional skills and dedication. After thorough evaluations, the RLFG is proud to reveal the players who have earned their spots on the national squads.</p>
<img src="/news/mens_team.jpeg" alt="">
<img src="/news/womens_team.png" alt="">
<img src="/news/youth.jpeg" alt="">
<p>The RLFG extends its heartfelt congratulations to all selected players. This diverse and talented roster promises a competitive and exciting year ahead for Ghanaian rugby league. We look forward to seeing these athletes represent our nation with pride and excellence.</p>', '/news/2.jpg', 'Official Announcements', array['Origins Cup', 'National Team']::text[], 'published', '2024-09-21'::timestamptz, '[{"type": "paragraph", "content": "The Rugby League Federation Ghana (RLFG) is thrilled to announce the selection of its 2024 national teams for men, women, and youth. This year marks a historic moment as the Federation names its first-ever Youth National Team, further demonstrating its commitment to nurturing young talent and ensuring a bright future for rugby league in Ghana."}, {"type": "paragraph", "content": "The selection process was rigorous and followed the recent 2024 Origins Cup, where players showcased their exceptional skills and dedication. After thorough evaluations, the RLFG is proud to reveal the players who have earned their spots on the national squads."}, {"type": "image", "src": "/news/mens_team.jpeg", "size": "contain"}, {"type": "image", "src": "/news/womens_team.png", "size": "contain"}, {"type": "image", "src": "/news/youth.jpeg", "size": "contain"}, {"type": "paragraph", "content": "The RLFG extends its heartfelt congratulations to all selected players. This diverse and talented roster promises a competitive and exciting year ahead for Ghanaian rugby league. We look forward to seeing these athletes represent our nation with pride and excellence."}]'::jsonb),
  ('polytank-supports-rugby-in-ghana', ' Polytank Supports Rugby in Ghana', 'The industry giant known for strength and durability, has teamed up with Rugby League Federation Ghana! This partnership blends the might of Polytank with the growing energy of rugby league, promising big wins for the sport’s future. Could this be the start of a lasting legacy in Ghana''s sports scene?', '<p>Polytank, a household name synonymous with durability and legacy in Ghana, brings its extensive brand reputation to the partnership. The company&#x27;s Business Head, Girender Mohinani, highlights the rationale behind choosing RLFG: The reason we chose the RLFG is because we see synergy between rugby league as a sport, with key values such as strength, durability, and power. Hopefully, this collaboration will continue to thrive.</p>
<p>Riddick Alibah, the Greater Accra Regional Manager, enthusiastically states, &#x27;This is a fantastic partnership that will undoubtedly contribute significantly to the development of the federation. Securing support has been challenging, but with Polytank—a legacy and durable brand in Ghana—joining forces, this is truly promising and uplifting.&#x27;</p>
<p>As this partnership unfolds, it marks a significant chapter in the sports history of Ghana, fusing the strength of Polytank&#x27;s brand with the resilience and dynamism of RLFG. The impact of this collaboration is poised to resonate not only within the rugby league community but with corporate Ghana and also across the broader landscape of sports enthusiasts in the country. With hopes that this is not just a one time collaboration  ,but the beginning of a long term partnership and a legacy building move. The 2024 championship is just the start but this will transcend to the future and the polytank brand will be attached to the sports in Ghana till the sport achieves all future successes.</p>', '/news/3.png', 'Official Announcements', array['Rugby', 'Community']::text[], 'published', '2024-08-21'::timestamptz, '[{"type": "paragraph", "content": "Polytank, a household name synonymous with durability and legacy in Ghana, brings its extensive brand reputation to the partnership. The company''s Business Head, Girender Mohinani, highlights the rationale behind choosing RLFG: The reason we chose the RLFG is because we see synergy between rugby league as a sport, with key values such as strength, durability, and power. Hopefully, this collaboration will continue to thrive."}, {"type": "gallery", "images": [{"type": "image", "alt_text": "", "src": ""}, {"type": "image", "alt_text": "", "src": ""}, {"type": "image", "alt_text": "", "src": ""}, {"type": "image", "alt_text": "", "src": ""}]}, {"type": "paragraph", "content": "Riddick Alibah, the Greater Accra Regional Manager, enthusiastically states, ''This is a fantastic partnership that will undoubtedly contribute significantly to the development of the federation. Securing support has been challenging, but with Polytank—a legacy and durable brand in Ghana—joining forces, this is truly promising and uplifting.''"}, {"type": "paragraph", "content": "As this partnership unfolds, it marks a significant chapter in the sports history of Ghana, fusing the strength of Polytank''s brand with the resilience and dynamism of RLFG. The impact of this collaboration is poised to resonate not only within the rugby league community but with corporate Ghana and also across the broader landscape of sports enthusiasts in the country. With hopes that this is not just a one time collaboration  ,but the beginning of a long term partnership and a legacy building move. The 2024 championship is just the start but this will transcend to the future and the polytank brand will be attached to the sports in Ghana till the sport achieves all future successes."}]'::jsonb),
  ('judiciary-report:-february-4,-rlfg-championship', ' Judiciary Report: February 4, RLFG championship', null, '', '/news/4.png', 'Regulatory', array['Championship', 'Official']::text[], 'published', '2024-07-26'::timestamptz, null),
